// The Cyrus HOST SEAM: everything Cyrus needs from the platform it runs inside, as small interfaces.
// Inside Nxeon the implementation is lib/cyrus/host/nxeon.ts (the ONLY file under lib/cyrus allowed to import Nxeon
// internals, enforced by test/cyrus-host-seam.test.ts). Standalone Cyrus supplies its own implementation of this
// interface (or an adapter that calls the Nxeon API). Add a method here when Cyrus needs a new platform service,
// never import the platform directly. Pure types: client-safe, type-only imports.

import type { ModBuild, PrismaClient, User } from "@prisma/client";
import type Stripe from "stripe";
import type { CreateBuildResult } from "../builder/types";
import type { PlatformClient } from "./platform";

/** Cyrus' OWN tables (the 27 Cyrus* models plus ModBuild, which has no relations to platform tables) and raw SQL, nothing else.
 *  Nxeon's tables (User, Server, ServerMod, GameMod, Job, Setting, Notification...) are deliberately absent: Cyrus reaches
 *  them only through the methods of CyrusHost, so a standalone Cyrus needs just its own database. */
export type CyrusDb = Pick<PrismaClient,
  | "modBuild" | "cyrusProject" | "cyrusRevision" | "cyrusProjectAsset"
  | "cyrusModelDraft" | "cyrusIdentifier" | "cyrusManagedPlugin" | "cyrusServerManagedPlugin"
  | "cyrusTokenAccount" | "cyrusTokenLot" | "cyrusTokenLedger" | "cyrusTokenReservation"
  | "cyrusPlan" | "cyrusModPage" | "cyrusModPost" | "cyrusModReport"
  | "cyrusFork" | "cyrusModListing" | "cyrusModMedia" | "cyrusRemix"
  | "cyrusModStar" | "cyrusModRating" | "cyrusLibraryItem" | "cyrusCreator"
  | "cyrusCollection" | "cyrusCollectionItem" | "cyrusCommunityReport" | "cyrusModSignal"
  | "cyrusCreatorAlert" | "cyrusCatalogEntry" | "cyrusCatalogReview" | "cyrusCatalogEnrichmentRun"
  | "cyrusCatalogTerm" | "cyrusLibraryDerivative" | "cyrusLibraryUse" | "cyrusLibraryReport" | "cyrusLibraryModeration" | "cyrusLibraryFingerprint"
  | "cyrusLegalCase" | "cyrusNotification" | "cyrusNotificationPref" | "cyrusTicketContext"
  | "cyrusPersonalApiKey" | "cyrusDataRequest" | "cyrusAttribution" | "cyrusConversion"
  | "cyrusStorageAccount" | "cyrusStorageCharge" | "cyrusStorageSnapshot" | "cyrusCoachEvent"
  | "$transaction" | "$queryRaw" | "$executeRaw" | "$queryRawUnsafe" | "$executeRawUnsafe">;

export type HostRateLimit = { ok: boolean; retryAfterSec: number; remaining: number };

/** The signed-in person as Cyrus sees them. The platform's own user record is a superset of this. */
export type HostUser = { id: string; email: string | null; role: string; name?: string | null };
/** A permission area of the host's admin ("billing", "support"...). Opaque to Cyrus; each host defines its own. */
export type HostArea = string;
/** Private-preview feature keys Cyrus may ask about. */
export type HostPreviewFeature = "modbuilder";

/** A game server's filesystem as installers see it (absolute guest paths). Structurally identical to the platform's GuestFs. */
export interface HostGuestFs {
  readonly kind: "ssh" | "local";
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  /** Creates parent directories. */
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  /** Move, overwriting a file at `to`. Creates the destination's parent. */
  rename(from: string, to: string): Promise<void>;
  /** File or directory (recursive). Missing is not an error. */
  remove(p: string): Promise<void>;
  /** Entry names; [] when missing. */
  list(dir: string): Promise<string[]>;
  /** Best-effort: give `paths` the owner/group of `ref` (real guests only). */
  chownLike(ref: string, paths: string[]): Promise<void>;
  copy(from: string, to: string): Promise<void>;
}
/** What the host knows about a game server (the guest itself is asked separately). */
export type HostServerFacts = { id: string; family: string; variant: string | null; pinnedVersion: string | null; config: Record<string, unknown> | null };
/** What the host's catalogue knows about a mod; Cyrus mints these for its own sources ("cyrus", managed plugins, mod packs). */
export type HostModFacts = {
  id: string; gameFamily: string; slug: string; name: string; source: string; sourceId: string | null; url: string | null; category: string;
  appliesToVariant: string | null; loaders: string[]; gameVersions: string[]; serverSide: string | null; targetVersionId?: string | null;
};
export type HostResolvedPackage = {
  key: string; name: string; version: string; versionId?: string | null;
  file: { url: string; filename: string; size: number | null; hashes: { sha1?: string | null; sha256?: string | null; sha512?: string | null } };
  /** "plugin-jar" | "datapack" for Minecraft. */
  placement: string;
  requires: string[]; incompatible: { key: string; name: string }[];
  /** The bytes, already fetched and verified by Cyrus: the host never downloads for Cyrus. */
  prefetched?: Buffer;
  root: boolean;
};
export type HostResolution = { packages: HostResolvedPackage[]; notes: string[]; alsoBackupDirs?: string[] };
export type HostInstallResult =
  | { ok: true; version?: string; versionId?: string | null; fileName?: string | null; restartRequired: boolean; changed: string[]; notes: string[] }
  | { ok: false; error: string };

/** A game server row as Cyrus reads it. The platform's own row is a superset. */
export type HostServerRow = {
  id: string; status: string; label?: string | null; hostname: string; gameVariant: string | null; gameConfig: unknown;
  osTemplate?: { family: string } | null;
};
/** One mod installed on one server (the platform's install record). */
export type HostInstallRow = {
  serverId: string; modId: string; versionId: string | null; status: string; error: string | null; updatedAt: Date; autoUpdate: string | null;
  mod: { source: string; sourceId: string | null; name: string };
};

export interface CyrusHost {
  /** Cyrus' own database (see CyrusDb). Use through lib/cyrus/db.ts (cyrusDb), not directly. */
  db: CyrusDb;
  /** Who is signed in. Sessions, cookies and impersonation stay entirely the host's business. */
  auth: {
    /** The acting user (impersonation applied), or null when signed out. */
    currentUser(): Promise<HostUser | null>;
    /** The really signed-in user, ignoring impersonation, or null. */
    realUser(): Promise<HostUser | null>;
    /** Page guard for an admin area: returns the real staff user, or ends the request (redirect/404) by the host's rule. */
    requireArea(area: HostArea): Promise<HostUser>;
  };
  /** Permission checks. Fail CLOSED: unknown role/area/feature is false. */
  access: {
    canAccess(role: string, area: HostArea): boolean;
    isPreviewUser(user: { email?: string | null } | null | undefined, feature: HostPreviewFeature): Promise<boolean>;
  };
  /** Key/value settings and feature flags (Nxeon: the Setting table). Values are strings; missing keys use the fallback. */
  settings: {
    get(key: string, fallback?: string): Promise<string>;
    getBool(key: string, fallback?: boolean): Promise<boolean>;
    getInt(key: string, fallback?: number): Promise<number>;
    getAll(): Promise<Record<string, string>>;
    set(key: string, value: string): Promise<void>;
    /** Values exactly as stored (no defaults, no cache): for admin editors that must tell "unset" from "default". */
    readStored(keys: string[]): Promise<Record<string, string>>;
    readStoredPrefix(prefix: string): Promise<Record<string, string>>;
    writeStored(key: string, value: string): Promise<void>;
    clearStored(key: string): Promise<void>;
  };
  /** Fixed-window rate limiter keyed by an opaque string. Synchronous, in-process. */
  rateLimit: {
    check(key: string, opts: { max: number; windowMs: number }): HostRateLimit;
  };
  /** Platform-side background work Cyrus's scheduler (lib/cyrus/worker/schedule.ts) drives but does not own. Each call is one sweep pass. */
  worker: {
    /** Installed-mod lifecycle on customer servers: Broken signals, crash-loop auto-disable, opt-in auto-updates. */
    modLifecycleSweep(): Promise<unknown>;
    /** Creator warnings about game versions the mod no longer fits. */
    modCompatWatchSweep(): Promise<unknown>;
    /** Advance in-flight AI mod builds from the build service. */
    syncModBuilds(): Promise<unknown>;
    /** Perf safety: watch customer servers for a few minutes after a Cyrus install; disable/roll back a mod that keeps
     *  the server under the TPS floor (worker/cyrus-perf-watch.ts). OPTIONAL: a host without it has no post-install watch. */
    perfWatchSweep?(): Promise<unknown>;
  };
  /** Accounts, by id. Billing identity is the host's; Cyrus only reads the basics and stores the payment customer id it creates. */
  users: {
    get(id: string): Promise<{ id: string; email: string } | null>;
    emails(ids: string[]): Promise<{ id: string; email: string }[]>;
    /** By email (case-insensitive) when `query` contains "@", otherwise by id. */
    find(query: string): Promise<{ id: string; email: string } | null>;
    setBillingCustomerId(userId: string, customerId: string): Promise<void>;
  };
  /** Background jobs the host queues (read side only). */
  jobs: {
    /** The newest finished job of one of `types` on a server, or null. */
    lastDone(serverId: string, types: string[]): Promise<{ updatedAt: Date; payload: unknown } | null>;
  };
  /** The host's game servers. */
  servers: {
    get(serverId: string): Promise<HostServerRow | null>;
    /** The user's servers that are not being deleted, oldest first. */
    listForUser(userId: string): Promise<HostServerRow[]>;
    /** Which game a server row is (e.g. "minecraft"), or null when it cannot be told. */
    familyOf(server: HostServerRow): string | null;
    /** The game family of the plan a server was bought on, or null. */
    planFamily(serverId: string): Promise<string | null>;
    /** How many paid (not free) game servers the user has. */
    paidCount(userId: string): Promise<number>;
    /** The newest "health" mod-update run on a server (log-read verdicts), or null. */
    lastHealthRun(serverId: string): Promise<{ startedAt: Date; plan: unknown } | null>;
    /** File access to ONE of this user's servers (null when it is not theirs, gone, or being deleted); `base` is the game folder on it. */
    openFiles(userId: string, serverId: string): Promise<{ fs: HostGuestFs; base: string; close?: () => void } | null>;
    /** The game version pinned in a server's config, when it names a real one. */
    pinnedVersion(config: unknown): string | null;
  };
  /** What the host has recorded as installed (its ServerMod/GameMod records). */
  records: {
    /** Installs on one server whose catalogue source is `source`. */
    onServer(serverId: string, source: string): Promise<HostInstallRow[]>;
    /** Which of `serverIds` have at least one install from `source` (each id once). */
    serversWithSource(serverIds: string[], source: string): Promise<string[]>;
    /** The catalogue entry id for a source's item, or null. */
    catalogId(source: string, sourceId: string): Promise<string | null>;
    /** Installs of one catalogue entry on any of `serverIds`. */
    ofMod(modId: string, serverIds: string[]): Promise<Omit<HostInstallRow, "mod">[]>;
    /** Everything the host recorded on one server, any source (names for prefills and the pre-install conflict report;
     *  "mods-tab" = the user's own Mods tab). Optional: absent = Cyrus reads the server's files instead. */
    allOnServer?(serverId: string): Promise<{ name: string; version: string | null; source: string; fileName: string | null; status: string; via: "mods-tab" | "cyrus" | "managed" | "other" }[]>;
  };
  /** Putting Cyrus' files on a server through the host's install engine (which keeps the host's own record of what it placed). */
  installs: {
    /** The engine's state file on the server; a pack install snapshots it so a failed install also undoes the bookkeeping. */
    readonly statePath: string;
    /** Place the prefetched package(s) of `resolution` for `mod`. Never downloads: a download attempt fails with `noDownloadMessage`. */
    install(a: { fs: HostGuestFs; server: HostServerFacts; mod: HostModFacts; resolution: HostResolution; mode: "install" | "update"; noDownloadMessage: string }): Promise<HostInstallResult>;
    /** Remove what the engine recorded for `mod` (and dependencies nothing else needs). */
    uninstall(a: { fs: HostGuestFs; server: HostServerFacts; mod: HostModFacts; noDownloadMessage: string }): Promise<HostInstallResult>;
  };
  /** Cyrus' build engine (lib/modbuilder: build rows, the build-service sync, the access rule). It is Cyrus' own code that
   *  still sits beside the platform; inside Nxeon these delegate to it unchanged. A standalone Cyrus passes its own. */
  builds: {
    /** Pull the build service's view of one build into its row (settles token holds when it finished). Never throws for an unreachable service. */
    sync(row: ModBuild): Promise<ModBuild>;
    /** Start a build or a change for `user` (plan, token and rate gates included). `body` is the build API's JSON. */
    create(user: User, body: Record<string, unknown>): Promise<CreateBuildResult>;
    /** The signed-in account allowed to use the Mod Builder (preview/public rule), or null. */
    accessUser(): Promise<User | null>;
    /** The same access rule for one account by id, without a session (API subjects), or null. */
    accountFor(userId: string): Promise<User | null>;
