export type CyrusAttachment = { n: number; name: string; type: string; size: number };

/** Plain JSON (assignable to Prisma's InputJsonValue). */
export type JsonValue = string | number | boolean | null | JsonValue[] | { [k: string]: JsonValue };
export type JsonObject = { [k: string]: JsonValue };

export type CyrusMeta = {
  model?: CyrusModelId;
  attachments?: CyrusAttachment[];
  title?: string;
  favourite?: boolean;
  /** D-63 (per PROJECT, root build): archived projects keep everything (installs, downloads, history) but no longer
   *  hold their game's slot; a game's slot frees when every project in it is archived (lib/cyrus/tokens/game-slots.ts). */
  archived?: boolean;
  notes?: string;
  headBuildId?: string;
  /** Cyrus mega staging (CYRUS_MEGA_STAGING): this build is one stage of a chain (lib/cyrus/planner/mega.ts parseStageChain). */
  stages?: import("./planner/mega").StageChain;
  /** v6 listing (see lib/cyrus/listing.ts). */
  category?: CyrusCategoryId;
  secondaryCategories?: CyrusCategoryId[];
  /** "auto" = the auto-sorter (or the migration helper) chose it; "owner" = the creator picked it. */
  categorySource?: "auto" | "owner";
  description?: string;
  icon?: string;
  /** data:image/webp|png;base64 of an uploaded icon (icon = "local:<rootId>"), small and bounded. */
  iconData?: string;
  /** Per BUILD (Cyrus R1): what custom assets the request asked for, what the plan + version allowed, and the
   *  customer-visible reasons for anything refused (lib/cyrus/assets/request.ts). Absent = no assets were asked for. */
  assets?: { requested: BuildAssetKind[]; allowed: BuildAssetKind[]; notices: string[]; projectId?: string; namespace?: string;
    /** Cyrus R2: the data pack route decision (lib/cyrus/datapack/route.ts); absent = the studio is off or nothing matched. */
    datapack?: { route: boolean; matched: string[]; limits: string[]; /** R4: the worldgen part was routed */ worldgen?: true };
    /** Cyrus R3: the gameplay designer route decision (lib/cyrus/designer/route.ts); absent = off or nothing matched. */
    designer?: { route: boolean; matched: string[]; limits: string[]; /** R3 menus/quests matched */ gameplay?: { menus: boolean; quests: boolean }; /** R3 bosses/encounters matched */ bosses?: true; /** R4 glyph HUDs matched */ hud?: true; /** motion core: motion props matched */ motion?: true };
    /** Cyrus R3: the item model states route decision (lib/cyrus/itemmodel/route.ts); absent = off or not routed. */
    itemStates?: { route: boolean; matched: string[] };
    /** Live-test fix (F): the lanes the mod planner + capability router approved for this build (lib/cyrus/planner). */
    planned?: { lanes: string[]; source?: "planner" | "rules" } };
  /** Per BUILD (Cyrus R5, server-side bookkeeping, stripped from customer views): what produced it
   *  (lib/cyrus/engine-core/release.ts). Kept through read/write round trips so a project patch never drops it. */
  engineRelease?: JsonObject;
  /** Per BUILD (Cyrus R5): the Test Flight gate's stored result (lib/cyrus/testflight/gate.ts StoredFlight). */
  testFlight?: JsonObject;
  /** Per BUILD (Cyrus r31): this build ships a Designer Studio revision (no model call). */
  designer?: { revisionId: string; seq: number; configOnly: boolean };
  /** Per BUILD (Cyrus starter bank): served from a prebuilt Nxeon entry with no model call (lib/cyrus/bank); charged the bank price. */
  bank?: { id: string; version: number; via: string };
