// Cyrus R5: the ENGINE RELEASE RECORD ("prove what built every mod"). One pure function combines what the build
// service reported for ONE build (services/modbuilder/release.js: prompt + section versions, API sheet / rules /
// scanner / registry / classpath hashes, JDK, allowlisted dependencies used) with what the portal itself knows (the
// artifact sha256 it re-hashed after download, its own registry hash, the service's /health facts) into one record.
// Stored on ModBuild.cyrus.engineRelease for EVERY succeeded build (asset or not) and, when the build gets a
// CyrusRevision, on that revision's `engine.release` (revisions are append-only, so it is written at creation).
// Nothing is guessed: a fact neither side knows is left out and named in `unknown`.
// Pure + client-safe. Game-agnostic (engine-core never names a game).
import { createHash } from "node:crypto";

export const ENGINE_RELEASE_SCHEMA = 1;
const SHA = /^[0-9a-f]{64}$/;

/** What the build service attached to a finished build (`release` on its record). Every field optional. */
export type SvcRelease = {
  schema?: number; service?: string; image?: string; promptVersion?: string | null; sections?: Record<string, string>;
  knowledge?: string | null; sheets?: { name: string; sha256: string }[]; rules?: { version: string | null; sha256: string | null };
  scanner?: { sha256: string | null; profile: string }; registrySha256?: string | null; jdk?: { release: number | null; version: string | null } | null;
  classpathSha256?: string | null; deps?: { id: string; sha256: string | null }[]; toolchain?: string | null;
};
/** The service's /health (only the fields used here). */
export type SvcHealthFacts = { image?: string; promptVersion?: string; knowledge?: string; release?: { image?: string; scannerSha256?: string | null; rulesSha256?: string | null; registrySha256?: string | null; depsManifestVersion?: string | null } };

export type EngineRelease = {
  schema: 1;
  /** Engine identity: a hash of the engine facts (target, prompts, knowledge, sheets, rules, scanner, service, registry, JDK,
   *  classpath, toolchain), NOT of this build's artifact, dependencies or model: two builds with the same id were produced
   *  by the same engine release. */
  id: string;
  recordedAt: string;
  target: string;
  prompts: { base?: string; sections?: Record<string, string> };
  knowledge?: string;
  sheets?: { name: string; sha256: string }[];
  rules?: { version?: string; sha256?: string };
  scanner?: { sha256?: string; profile?: string };
  service?: { name?: string; image?: string };
  registry?: { portal?: string; service?: string; match?: boolean };
  jdk?: { release?: number; version?: string };
  artifact: { kind: string; name?: string; sha256: string };
  classpathSha256?: string;
  /** SBOM-lite: the allowlisted compile-only dependencies this build used (id + sha256). Empty = none. */
  sbom: { id: string; sha256?: string }[];
  toolchain?: string;
  model?: string;
  /** Facts that were not known for this build (service too old, /health unreachable, ...). */
  unknown: string[];
};

export type ReleaseInput = {
  target: string;
  artifact: { kind: string; name?: string | null; sha256: string };
  svc?: SvcRelease | null;
  /** Fallbacks from the service build record when it has no `release` (older image). */
  record?: { promptVersion?: string | null; knowledge?: string | null; model?: string | null; sectionVersions?: Record<string, string | null | undefined> };
  health?: SvcHealthFacts | null;
  portalRegistrySha256?: string | null;
  now?: Date;
};

const str = (v: unknown, max = 200): string | undefined => (typeof v === "string" && v.trim() ? v.trim().slice(0, max) : undefined);
const hex = (v: unknown): string | undefined => (typeof v === "string" && SHA.test(v) ? v : undefined);
const prune = <T extends Record<string, unknown>>(o: T): T => { for (const k of Object.keys(o)) if (o[k] === undefined || (typeof o[k] === "object" && o[k] !== null && !Array.isArray(o[k]) && !Object.keys(o[k] as object).length)) delete o[k]; return o; };

export function canonicalJson(v: unknown): string {
  if (v === null || typeof v !== "object") return JSON.stringify(v) ?? "null";
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(",")}]`;
  const o = v as Record<string, unknown>;
  return `{${Object.keys(o).filter((k) => o[k] !== undefined).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(o[k])}`).join(",")}}`;
}
export const sha256Hex = (s: string | Buffer) => createHash("sha256").update(s).digest("hex");

/** Build the record. Pure: same input, same record (recordedAt from `now`). */
export function buildEngineRelease(i: ReleaseInput): EngineRelease {
  if (!hex(i.artifact.sha256)) throw new Error("engine release: artifact sha256 is required");
  const s = i.svc ?? {};
  const rec = i.record ?? {};
  const sections: Record<string, string> = {};
  for (const [k, v] of Object.entries({ ...(rec.sectionVersions ?? {}), ...(s.sections ?? {}) })) { const t = str(v, 80); if (t && /^[a-z0-9_]{1,24}$/.test(k)) sections[k] = t; }
  const sbom = (Array.isArray(s.deps) ? s.deps : []).filter((d) => d && str(d.id, 80)).map((d) => prune({ id: str(d.id, 80)!, sha256: hex(d.sha256) })).sort((a, b) => (a.id < b.id ? -1 : 1)).slice(0, 50);
// Cyrus R5: the TEST FLIGHT GATE (pure half). After a build succeeds and scans clean, the worker boots it once on a
// disposable Paper server for the build's own version (node-2, ./client.ts) with its jar, its data packs and (when the
// Pack Loader jar is available) its pack config, and stores an HONEST per-check result on the build:
//   compile, scan, boot, plugins enabled, commands registered, data pack loaded  (each pass / fail / not_run)
// "not run" is never shown as passed; the verdict only ever feeds a "boot-tested on <version>" label (a boot proves
// the plugin loads and its commands register, never how it behaves in game). Optional: block publishing / installing a
// build whose flight FAILED (CYRUS_TESTFLIGHT_BLOCK_ON_FAIL=1).
// Flags (all OFF): CYRUS_TESTFLIGHT_GATE=1 runs flights; CYRUS_TESTFLIGHT_BLOCK_ON_FAIL=1 blocks on a failed flight.
// Limits: one flight at a time per worker (node-2 runs one anyway; "busy" is retried with backoff), at most
// MAX_FLIGHTS_PER_BUILD real flights per build (per-build cost cap) and MAX_BUSY_RETRIES busy retries.
import { getVersion } from "../versions/registry";
import type { CheckResult, RconCheck, TestFlightReport, TestFlightSpec, TestFlightSummary } from "./types";
import { stressBlocks, type StoredStress } from "./stress";
import type { StoredWorldgen } from "./worldgen";
import type { StoredFunctional } from "./oracle/types";

export const GATE_FLAG = "CYRUS_TESTFLIGHT_GATE";
export const BLOCK_FLAG = "CYRUS_TESTFLIGHT_BLOCK_ON_FAIL";
export const MAX_FLIGHTS_PER_BUILD = 2;
export const MAX_BUSY_RETRIES = 12;
export const MAX_COMMAND_CHECKS = 8;
export const GATE_VERSION = "tfgate-1";

export const GATE_CHECKS = ["compile", "scan", "boot", "plugins_enabled", "commands_registered", "datapack_loaded"] as const;
export type GateCheckId = (typeof GATE_CHECKS)[number];
export type GateCheck = { id: GateCheckId; status: "pass" | "fail" | "not_run"; detail: string };
/** rc13: "passed_with_warnings" = the server booted and the plugin enabled, but a command the build LISTS did not register
 *  (fire-sword QA 2026-10-14 was "passed" with commands_registered FAILED). Honest, never shown as a clean pass, never blocks. */
export type GateVerdict = "passed" | "passed_with_warnings" | "failed" | "incomplete" | "not_run";

/** What is stored on ModBuild.cyrus.testFlight (plain JSON, small). */
export type StoredFlight = {
  schema: 1;
  gate: string;
  state: "queued" | "running" | "done" | "not_run" | "gave_up";
  version: string;
  verdict: GateVerdict;
  /** "boot-tested on Paper <version>" only when every required check passed; never about in-game behaviour. */
  label: string | null;
  checks: GateCheck[];
  reason?: string;
  flights: number;
  busyRetries: number;
  nextAt?: string;
  lastError?: string;
  runId?: string | null;
  bootMs?: number | null;
  peakRssKb?: number | null;
  engine?: { runner?: string; paperBuild?: number; jdk?: string | null } | null;
  notes?: string[];
  /** Wiring 2 (CYRUS_PLAYTEST): the playtest bots' verdict from the build's stored ModSpec, kept APART from the boot
   *  verdict (a playtest never changes `verdict` / `label`). Absent = the switch was off. */
  playtest?: { verdict: "passed" | "failed" | "incomplete" | "not_run"; label: string; counts?: { planned: number; ran: number; passed: number; failed: number; notRun: number }; scenarios?: { id: string; status: string; reason: string | null }[]; specRevisionId?: string | null } | null;
  /** R42: the vanilla reference checks of the build's packs (copied from ModBuild.result.assets.vanilla). Never changes
   *  `verdict` / `label`: a pack that overrides vanilla still boots; this is a warning for the owner and the customer. */
  vanilla?: { status: "checked" | "not_run"; version: string; counts: { error: number; warn: number; info: number }; issues: { code: string; severity: string; path: string; message: string }[] } | null;
  /** Perf safety: the STRESS phase (./stress.ts storedStress), kept apart from the boot verdict. A FAILED stress blocks
   *  Install by default (flightBlocks). Absent = not flown (switch off or an older flight). */
