export type GdprPlanRow = GdprTable & { rows: number | null };

/** Plan an erasure from per-table row counts (null = the table is not in this database yet). */
export function gdprPlan(counts: Record<string, number | null>): { rows: GdprPlanRow[]; delete: number; anonymise: number; retain: number } {
  const rows = CYRUS_GDPR_TABLES.map((t) => ({ ...t, rows: counts[t.model] ?? null }));
  const sum = (p: GdprPolicy) => rows.filter((r) => r.policy === p).reduce((s, r) => s + (r.rows ?? 0), 0);
  return { rows, delete: sum("delete"), anonymise: sum("anonymise"), retain: sum("retain") };
}

/** The anonymised stand-in for a user id (stable per user, not reversible without the salt kept in the audit row). */
export const ANON_USER = (userId: string, salt: string) => `erased_${createHash("sha256").update(`${salt}:${userId}`).digest("hex").slice(0, 16)}`;

