/// First-party web events from cyrus.my (the static landing beacon and the Cyrus app pages), HUMAN-looking traffic only
/// (a bot hit is only counted, in CyrusDailyMetrics "web.bot_hits"). No IP address, no user agent, no cookie value, no
/// prompt text. `vid`/`sid`/`ref` exist only when the visitor gave analytics consent (consent = "analytics"). Rows older
/// than 90 days are purged by the nightly rollup (lib/cyrus/analytics/rollup.ts); the aggregates are kept.
model CyrusWebEvent {
  id        String   @id @default(cuid())
  at        DateTime @default(now())
  /// view | scroll50 | scroll90 | prompt_focus | prompt_submit | plans_view | signin_click | signup_click
  event     String
  host      String
  /// Normalised path (lib/cyrus/analytics/web.ts normalizePath): no query, ids replaced.
  path      String
  /// Rotating random visitor id (30 days), analytics consent only.
  vid       String?
  /// Per-tab session id, analytics consent only.
  sid       String?
  /// First page load of this vid (consented only).
  isNew     Boolean?
  /// direct | search | ai | social | email | paid | referral
  src       String
  /// chatgpt | perplexity | google | reddit ... (see web.ts)
  srcName   String?
  /// Referrer HOSTNAME only (never a path or query).
  refHost   String?
  utmSource   String?
  utmMedium   String?
  utmCampaign String?
  /// Creator partner code from ?ref=, analytics consent only.
  ref       String?
  /// ISO-3166 alpha-2 from the IP at ingest (the IP itself is not stored).
  country   String?
  /// Desktop | Mobile | Tablet | Other
  device    String?
  /// none | analytics: what the visitor had agreed to when the row was written.
  consent   String   @default("none")

  @@index([at])
  @@index([event, at])
  @@index([vid, at])
  @@index([sid, at])
}

/// Durable daily aggregates (kept; raw events are not). One row per (UTC day, key, dim). `dim` is "" for the total or a
