/// (lib/cyrus/analytics/rollup.ts) from raw events and from existing product facts; idempotent per (date, key, dim).
model CyrusDailyMetrics {
  id        String   @id @default(cuid())
  date      DateTime
  key       String
  dim       String   @default("")
  value     Float
  updatedAt DateTime @updatedAt

  @@unique([date, key, dim])
  @@index([key, date])
}

/// Product events that exist as no other fact. Today ONE kind: plan_shown (the plan screen answered for an account:
