// The Nxeon implementation of the Cyrus host seam. SERVER ONLY. This is the single file under lib/cyrus/host that
// reaches Nxeon: every method delegates to the existing platform function unchanged, so behaviour inside Nxeon is
// identical to calling them directly. Moving Cyrus out means replacing this file, nothing else.
import { getSetting, getSettingBool, getSettingInt, getAllSettings, setSetting } from "../../settings";
import { checkRateLimit } from "../../rate-limit";
import { recordAudit } from "../../audit";
import { currentUser, realUser } from "../../auth";
import { canAccess, requireArea, type Area } from "../../rbac";
import { isPreviewUser } from "../../preview-access";
import { db } from "../../db";
import { SANDBOX } from "../../sandbox";
import { pinnedVersion } from "../../mods/facts";
import { familyFor } from "../../game-config";
import { STATE_PATH } from "../../mods/engine";
import { stripe, stripeConfigured, stripePublishableKey, createCheckoutSessionLogged, CUSTOM_CHECKOUT_UI_MODE, EMBEDDED_REQUEST_OPTS } from "../../stripe";
import { debitWallet, InsufficientBalanceError } from "../../wallet";
import type { FamilyInstaller, Resolution } from "../../mods/types";
import type { CyrusHost, HostBilling, HostModFacts, HostResolution, HostWallet } from "./types";
import { purchaseSender } from "../../cyrus-client/purchase-events";
import { cyrusConfig } from "../config";
import { PrismaClient } from "@prisma/client";
import { cyrusDatabaseUrl } from "./db-url";

/** The Minecraft installer, with resolve() replaced by Cyrus' own prefetched resolution (detect/place/compat unchanged). */
const prefetchedInstaller = async (mod: HostModFacts, resolution: HostResolution | null): Promise<FamilyInstaller> => {
  const { minecraftInstaller } = await import("../../mods/installers/minecraft");
  return {
    ...minecraftInstaller,
    sources: [mod.source],
    resolve: async () => (resolution ?? { packages: [], notes: [] }) as Resolution,
    legacyPaths: () => [],
  };
};
const noNetwork = (message: string) => async (): Promise<never> => {
  const { FetchError } = await import("../../mods/safe-fetch");
  throw new FetchError(message, "host");
};

// The wallet option of host.billing. Same debit as every Nxeon product (conditional decrement, never negative) plus the
// usual WalletTransaction row; a refund credits real funds (untagged row). Nothing in Cyrus calls it today.
const okCents = (c: number) => Number.isInteger(c) && c > 0 && c <= 10_000_000;
const refTag = (r: string) => ` [ref:${r}]`;
const withRef = (d: string, r?: string) => (r ? d.slice(0, 200 - refTag(r).length) + refTag(r) : d.slice(0, 200));
const okRef = (r?: string) => r === undefined || /^[A-Za-z0-9:_-]{8,120}$/.test(r);
const nxeonWallet: HostWallet = {
  balance: async (userId) => (await db.user.findUnique({ where: { id: userId }, select: { balanceCents: true } }))?.balanceCents ?? null,
  async charge({ userId, cents, description, reference }) {
    if (!okCents(cents) || !description || !okRef(reference)) return { ok: false, error: "invalid" };
    try {
      return await db.$transaction(async (tx) => {
        // Idempotent per reference (single statement order inside the transaction; a unique reference column for
        // several instances is the SQL proposal in OWNER-ACTIONS).
        if (reference && (await tx.walletTransaction.findFirst({ where: { userId, amountCents: { lt: 0 }, description: { endsWith: refTag(reference) } }, select: { id: true } }))) return { ok: true as
        await debitWallet(tx, userId, cents);
        await tx.walletTransaction.create({ data: { userId, amountCents: -cents, description: withRef(description, reference) } });
        return { ok: true as const };
      });
    } catch (e) {
      if (e instanceof InsufficientBalanceError) return { ok: false, error: "insufficient_funds" };
      throw e;
