    catalogId: async (source, sourceId) => (await db.gameMod.findFirst({ where: { source, sourceId }, select: { id: true } }))?.id ?? null,
    ofMod: (modId, serverIds) => db.serverMod.findMany({ where: { modId, serverId: { in: serverIds } } }),
    allOnServer: async (serverId) => (await db.serverMod.findMany({ where: { serverId, status: { notIn: ["REMOVED"] } }, include: { mod: { select: { name: true, source: true } } }, orderBy: { installedAt: "asc" }, take: 
      .map((r) => ({ name: r.mod.name, version: r.version ?? null, source: r.mod.source, fileName: r.fileName ?? null, status: r.status, via: r.mod.source === "cyrus" ? "cyrus" as const : r.mod.source === "nxeon-managed"
  },
