  // keeps the host free of import cycles). Same functions as before.
  builds: {
    sync: async (row) => (await import("../../modbuilder/store")).syncBuild(row),
    create: async (user, body) => (await import("../../modbuilder/create")).createModBuild(user, body),
    accessUser: async () => (await import("../../modbuilder/access")).modBuilderUser(),
    accountFor: async (userId) => {
      const user = await db.user.findUnique({ where: { id: userId } });
      return user ? (await import("../../modbuilder/access")).modBuilderAccess(user) : null;
    },
    mergeCyrusKey: async (id, key, value) => (await import("../../modbuilder/store")).mergeCyrusKey(id, key, value),
  },
  mods: {
    serviceBuildId: async (buildId) => (await import("../../cyrus-mods/registry")).serviceBuildId(buildId),
    onBuildSettled: async (row) => (await import("../../cyrus-mods/pages")).onBuildSettled(row),
  },
  // r40: Cyrus notification email goes out through Nxeon's own mailer (same relay, EmailLog row, tracking).
  mail: {
    send: async (m) => (await import("../../mailer")).sendMail({ to: m.to, from: m.from, replyTo: m.replyTo, subject: m.subject, html: m.html, text: m.text, userId: m.userId }),
  },
  conversions: {
    meta: async (e) => (await import("../../cyrus-bridge/conversions")).sendMetaEvent(e),
    google: async (e, userId) => (await import("../../cyrus-bridge/conversions")).queueGoogleConversion(e, userId),
  },
  billing: {
    provider: "host",
    stripe: {
      configured: () => stripeConfigured(),
      client: () => stripe(),
      publishableKey: () => stripePublishableKey(),
      createCheckoutSession: (params, options) => createCheckoutSessionLogged(params, options),
      // getters: lib/stripe's graph reaches this file back, so read its constants at use, not at load
      get uiMode() { return CUSTOM_CHECKOUT_UI_MODE; },
      get requestOptions() { return EMBEDDED_REQUEST_OPTS; },
      ensureCustomer: async (user) => (await import("../../stripe-cards")).ensureStripeCustomer(user),
    },
    wallet: nxeonWallet,
    // CYRUS_PURCHASE_EVENTS: completed/refunded purchases reach Cyrus as signed webhooks (lib/cyrus-client). Off = direct.
    get emitPurchase() {
      const sender = purchaseSender();
      return sender ? (e: Parameters<NonNullable<HostBilling["emitPurchase"]>>[0]) => sender.send(e) : undefined;
    },
    // r38 CYRUS_PLATFORM_EVENTS: plan changes reach a standalone Cyrus as signed entitlement.changed events. Off = absent.
    get entitlementChanged() {
      if (process.env.CYRUS_PLATFORM_EVENTS !== "1") return undefined;
      return async (userId: string) => (await import("../../nxeon-platform/entitlements")).notifyEntitlementChanged(userId);
    },
  },
  audit: {
    record: (userId, action, detail) => recordAudit(userId, action, detail),
    append: async (row) => { await db.auditLog.create({ data: row }); },
  },
};

