// Cyrus analytics, NXEON SIDE: the platform facts the Cyrus analytics page reads that live in Nxeon's own tables
// (User, ActivityEvent, Visit, the Search Console connection). Reached only through lib/cyrus/host/nxeon.ts
// (host.analytics). Read-only, aggregate-friendly: no IP, no user agent, no email leaves this file.
import { db } from "@/lib/db";
import type { HostCyrusVisit, HostGscResult } from "@/lib/cyrus/host/types";

/** The ActivityEvent `auth.login` methods written by the Cyrus-host callbacks (app/cyrus-host/auth/*). */
export const CYRUS_LOGIN_METHODS = ["nxeon-sso", "google-cyrus"] as const;

export async function accountFacts(ids: string[]): Promise<{ id: string; createdAt: Date; verified: boolean }[]> {
  const uniq = [...new Set(ids.filter(Boolean))].slice(0, 20000);
  if (!uniq.length) return [];
  const out: { id: string; createdAt: Date; verified: boolean }[] = [];
  for (let i = 0; i < uniq.length; i += 2000) {
    const rows = await db.user.findMany({ where: { id: { in: uniq.slice(i, i + 2000) } }, select: { id: true, createdAt: true, emailVerifiedAt: true } });
    for (const r of rows) out.push({ id: r.id, createdAt: r.createdAt, verified: !!r.emailVerifiedAt });
  }
  return out;
}

export async function firstCyrusSignIns(sinceMs: number, limit: number): Promise<{ userId: string; at: Date; method: string }[]> {
  const where = {
    category: "auth", type: "auth.login", userId: { not: null },
    OR: CYRUS_LOGIN_METHODS.map((m) => ({ data: { path: ["method"], equals: m } })),
  };
  // the EARLIEST per account over all time, then only the ones whose first is inside the window
  const g = await db.activityEvent.groupBy({ by: ["userId"], where, _min: { createdAt: true }, take: 50000 });
  const first = g.filter((r) => r.userId && r._min.createdAt && r._min.createdAt.getTime() >= sinceMs).slice(0, limit);
  if (!first.length) return [];
  const ids = first.map((r) => r.userId!) as string[];
  const methods = await db.activityEvent.findMany({ where: { ...where, userId: { in: ids } }, orderBy: { createdAt: "asc" }, select: { userId: true, createdAt: true, data: true }, take: ids.length * 4 });
  const byUser = new Map<string, string>();
  for (const m of methods) {
    if (m.userId && !byUser.has(m.userId)) {
      const meth = (m.data as { method?: unknown } | null)?.method;
      byUser.set(m.userId, typeof meth === "string" ? meth.slice(0, 30) : "unknown");
    }
  }
  return first.map((r) => ({ userId: r.userId!, at: r._min.createdAt!, method: byUser.get(r.userId!) ?? "unknown" }));
}

export async function cyrusVisits(a: { sinceMs: number; untilMs: number; limit: number }): Promise<HostCyrusVisit[]> {
  try {
    const rows = await db.visit.findMany({
      where: { product: "cyrus", createdAt: { gte: new Date(a.sinceMs), lt: new Date(a.untilMs) } },
      orderBy: { createdAt: "desc" }, take: Math.min(a.limit, 50000),
      select: { createdAt: true, host: true, path: true, referrer: true, country: true, deviceType: true, isBot: true, botKind: true, webdriver: true, interacted: true, userId: true },
    });
    return rows.map((r) => ({ at: r.createdAt, host: r.host, path: r.path, referrer: r.referrer, country: r.country, deviceType: r.deviceType, isBot: r.isBot, botKind: r.botKind, webdriver: r.webdriver, interacted: r.interacted, signedIn: !!r.userId }));
  } catch {
    return []; // columns not created yet (db push pending): the page says so
  }
}

let gscCache: { at: number; days: number; v: HostGscResult } | null = null;
const GSC_TTL = 30 * 60_000;

/** Search Console for the cyrus.my property, through the platform's single read-only connection. Never throws. */
export async function cyrusSearchConsole(a: { days: number }): Promise<HostGscResult> {
  if (gscCache && gscCache.days === a.days && Date.now() - gscCache.at < GSC_TTL) return gscCache.v;
  const done = (v: HostGscResult) => { gscCache = { at: Date.now(), days: a.days, v }; return v; };
  try {
    const gsc = await import("@/lib/seo/searchConsole");
    const st = await gsc.getGscConnectionStatus();
    if (!st.connected) return done({ state: "not_connected", message: "Search Console is not connected on the platform (Admin > SEO).", rows: [] });
    const tok = await gsc.resolveGscAccessToken();
    if (!tok.accessToken) return done({ state: "error", message: tok.error ?? "Could not get a Search Console token.", rows: [] });
    const sites = await gsc.gscListSites(tok.accessToken);
    if (!sites.sites) return done({ state: "error", message: sites.error ?? "Could not list Search Console properties.", rows: [] });
    const cyrus = sites.sites.filter((s) => /(^|[:/.])cyrus\.my\/?$/i.test(s.siteUrl.replace(/^https?:\/\//, "").replace(/^sc-domain:/, "")) || s.siteUrl === "sc-domain:cyrus.my");
    const siteUrl = cyrus.find((s) => s.siteUrl === "sc-domain:cyrus.my")?.siteUrl ?? cyrus[0]?.siteUrl ?? null;
    if (!siteUrl) return done({ state: "no_property", message: "The connected Google account has no cyrus.my property yet (see docs/cyrus/18-seo.md, Search Console runbook).", rows: [] });
    const q = await gsc.gscQuerySearchAnalytics({ accessToken: tok.accessToken, siteUrl, days: Math.max(1, Math.min(90, a.days)), rowLimit: 1000 });
    if (!q.rows) return done({ state: "error", message: q.error ?? "Search Console query failed.", rows: [] });
    return done({ state: "ok", siteUrl, fetchedAt: new Date().toISOString(), rows: q.rows });
  } catch (e) {
    return { state: "error", message: (e as Error).message.slice(0, 200), rows: [] };
  }
}
