const COUNTRY = /^[A-Z]{2}$/;
const OPAQUE_SEG = /^(?:[0-9a-f]{16,}|cp[0-9a-f]{20}|c[a-z0-9]{24}|[0-9]{6,})$/;

export const cleanUtm = (v: unknown): string | null => (typeof v === "string" && UTM.test(v.trim()) ? v.trim() : null);
export const cleanRef = (v: unknown): string | null => (typeof v === "string" && REF.test(v) ? v : null);
export const cleanId = (v: unknown): string | null => (typeof v === "string" && ID.test(v) ? v : null);

/** A stored path: no query, no fragment, lower case, opaque ids replaced by ":id", at most 5 segments. Garbage = "/(other)". */
export function normalizePath(raw: unknown): string {
  if (typeof raw !== "string") return "/(other)";
  let p = raw.split(/[?#]/)[0].trim().toLowerCase();
  if (!p.startsWith("/") || p.length > 200) return "/(other)";
  p = p.replace(/\/{2,}/g, "/");
  if (p.length > 1) p = p.replace(/\/+$/, "");
  if (!/^\/[a-z0-9/_.:-]*$/.test(p)) return "/(other)";
  const segs = p.split("/").filter(Boolean).slice(0, 5).map((s) => (OPAQUE_SEG.test(s) ? ":id" : s));
  return "/" + segs.join("/");
}

export const deviceBucket = (t: string | null | undefined): "Desktop" | "Mobile" | "Tablet" | "Other" =>
  t === "Mobile" || t === "Tablet" || t === "Desktop" ? t : "Other";

/** Same human rule as lib/conversion-metrics.ts isHumanVisit (kept equal by test/cyrus-analytics.test.ts). */
export function isHumanHit(v: { isBot: boolean; botKind: string | null; webdriver: boolean | null }): boolean {
  return !v.isBot && (v.botKind === null || v.botKind === "human") && v.webdriver !== true;
}

// ---------------------------------------------------------------------------
// The collector decision
// ---------------------------------------------------------------------------

export type HitInput = {
  /** CYRUS_ANALYTICS=1 */
  enabled: boolean;
  /** The request came in on a Cyrus host (middleware marker). */
  onCyrusHost: boolean;
  /** The Host the browser used (cyrus.my). */
  host: string;
  headers: { dnt?: string | null; secGpc?: string | null; cookie?: string | null; origin?: string | null };
  /** The parsed JSON body (unknown shape). */
  body: unknown;
  /** Bot verdict for this request (null = not classified; treated as human). */
  bot: { isBot: boolean; botKind: string | null } | null;
  country: string | null;
  deviceType: string | null;
  now: number;
  ownHosts?: string[];
};

export type CleanWebRow = {
  at: Date; event: WebEvent; host: string; path: string; vid: string | null; sid: string | null; isNew: boolean | null;
  src: SourceClass; srcName: string | null; refHost: string | null; utmSource: string | null; utmMedium: string | null; utmCampaign: string | null;
  ref: string | null; country: string | null; device: string; consent: "none" | "analytics";
};

export type HitDecision =
  | { kind: "drop"; reason: "disabled" | "wrong_host" | "dnt" | "gpc" | "invalid" | "bad_event" | "cross_origin" }
  | { kind: "bot"; botKind: string }
  | { kind: "store"; row: CleanWebRow };

/** The beacon's own opt-out rule (also in the client script): DNT "1" or GPC true = send nothing at all. */
export function optOutSignal(h: { dnt?: string | null; secGpc?: string | null }): "dnt" | "gpc" | null {
  if (h.secGpc?.trim() === "1") return "gpc";
  if (h.dnt?.trim() === "1") return "dnt";
  return null;
}

export function decideHit(i: HitInput): HitDecision {
  if (!i.enabled) return { kind: "drop", reason: "disabled" };
  if (!i.onCyrusHost) return { kind: "drop", reason: "wrong_host" };
  const opt = optOutSignal(i.headers);
  if (opt) return { kind: "drop", reason: opt };
  // same-origin only: a cross-site page cannot feed the counters (the beacon is same-origin on cyrus.my)
  if (i.headers.origin) {
    let ok = false;
    try { ok = new URL(i.headers.origin).hostname.toLowerCase() === i.host.toLowerCase(); } catch { ok = false; }
    if (!ok) return { kind: "drop", reason: "cross_origin" };
  }
  const b = i.body && typeof i.body === "object" && !Array.isArray(i.body) ? (i.body as Record<string, unknown>) : null;
  if (!b) return { kind: "drop", reason: "invalid" };
  if (!isWebEvent(b.e)) return { kind: "drop", reason: "bad_event" };
  // webdriver from the beacon is one more bot signal (navigator.webdriver)
  const wd = b.wd === 1 || b.wd === true;
  if (wd || (i.bot && i.bot.isBot)) return { kind: "bot", botKind: wd && !(i.bot && i.bot.isBot) ? "webdriver" : (i.bot?.botKind ?? "suspected-bot") };

  const consent = parseConsent(cookieValue(i.headers.cookie, "cyrus_consent"));
  const analytics = !!consent?.analytics && consentFresh(consent.at, i.now);
  const refHost = referrerHostOf(b.r);
  const utmSource = cleanUtm(b.us), utmMedium = cleanUtm(b.um), utmCampaign = cleanUtm(b.uc);
  const own = i.ownHosts ?? [i.host.toLowerCase(), "cyrus.my", "www.cyrus.my"];
  const { src, srcName } = classifySource({ refHost, utmSource, utmMedium, ownHosts: own });
  const internal = !!refHost && own.some((d) => hostIs(refHost, d.replace(/^www\./, "")));
  return {
    kind: "store",
    row: {
      at: new Date(i.now), event: b.e, host: i.host.toLowerCase().slice(0, 80), path: normalizePath(b.p),
      vid: analytics ? cleanId(b.v) : null, sid: analytics ? cleanId(b.s) : null, isNew: analytics && (b.n === 1 || b.n === true) ? true : analytics ? false : null,
      src, srcName: srcName ? srcName.slice(0, 60) : null, refHost: internal ? null : refHost,
      utmSource, utmMedium, utmCampaign, ref: analytics ? cleanRef(b.f) : null,
      country: i.country && COUNTRY.test(i.country) ? i.country : null, device: deviceBucket(i.deviceType),
      consent: analytics ? "analytics" : "none",
    },
  };
}

/** The choice is only as good as its age (180 days, lib/cyrus/analytics/consent.ts CONSENT_MAX_AGE_S) and a clock in the future is no consent. */
function consentFresh(atMs: number, nowMs: number): boolean {
  return atMs <= nowMs + 300_000 && nowMs - atMs <= 180 * 86_400_000;
}

export function cookieValue(header: string | null | undefined, name: string): string | null {
  if (!header) return null;
  for (const part of header.split(";")) {
    const t = part.trim();
    if (t.startsWith(name + "=")) return t.slice(name.length + 1);
  }
  return null;
}

/** Should the client replace its anonymous id? (older than VID_ROTATE_DAYS, malformed, or from the future) */
export function vidExpired(createdMs: number | null | undefined, nowMs: number): boolean {
  if (typeof createdMs !== "number" || !Number.isFinite(createdMs)) return true;
  return createdMs > nowMs + 60_000 || nowMs - createdMs > VID_ROTATE_DAYS * 86_400_000;
}

// ---------------------------------------------------------------------------
// The Nxeon page tracker (/api/track): host + product dimension
// ---------------------------------------------------------------------------

const HOSTNAME = /^[a-z0-9]([a-z0-9.-]{0,120}[a-z0-9])?$/;
/** Cyrus surfaces that live on the Nxeon host (the studio inside the portal, NxLabs Cyrus mods, the Cyrus marketing page). */
export const CYRUS_PATH_PREFIXES = ["/dashboard/cyrus", "/mods/cyrus", "/cyrus", "/studio"];

/** host = lower-cased hostname (no port) or null; product = "cyrus" for a Cyrus host or a Cyrus surface path, else "nxeon". */
export function trackDimensions(hostHeader: string | null | undefined, path: string, cyrusHosts: string[]): { host: string | null; product: "cyrus" | "nxeon" } {
  const h = (hostHeader ?? "").toLowerCase().split(":")[0].trim();
  const host = HOSTNAME.test(h) ? h : null;
  const onCyrusHost = !!host && cyrusHosts.map((x) => x.toLowerCase()).includes(host);
  const p = (path || "/").split(/[?#]/)[0].toLowerCase();
  const surface = CYRUS_PATH_PREFIXES.some((x) => p === x || p.startsWith(x + "/"));
  return { host, product: onCyrusHost || surface ? "cyrus" : "nxeon" };
}

