// Cyrus analytics, PURE metric maths. No DB, no network, client-safe. Every function takes the rows the caller fetched and
// returns numbers or null: an empty input gives zeros / null, never an invented figure. The definitions printed on the
// admin page are in ./definitions.ts and describe exactly these functions. Unit-tested with fixtures in
// test/cyrus-analytics.test.ts.
import type { SourceClass, WebEvent } from "./web";
import { classifySource } from "./web";

export const DAY = 86_400_000;
export const utcDay = (ms: number) => Math.floor(ms / DAY) * DAY;
export const dayKey = (ms: number) => new Date(utcDay(ms)).toISOString().slice(0, 10);
/** Monday 00:00 UTC of the week containing `ms`. */
export function weekStart(ms: number): number {
  const d = utcDay(ms);
  const dow = (new Date(d).getUTCDay() + 6) % 7; // Monday = 0
  return d - dow * DAY;
}

export function median(xs: number[]): number | null {
  const v = xs.filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
  if (!v.length) return null;
  const m = v.length >> 1;
  return v.length % 2 ? v[m] : (v[m - 1] + v[m]) / 2;
}
export const mean = (xs: number[]): number | null => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
export const ratio = (a: number, b: number): number | null => (b > 0 ? a / b : null);
const r1 = (x: number) => Math.round(x * 10) / 10;

// ===========================================================================
// WEB (cyrus.my): human events from CyrusWebEvent
// ===========================================================================

export type WebRow = {
  at: number; event: WebEvent; path: string; vid: string | null; sid: string | null; isNew: boolean | null;
  src: SourceClass; srcName: string | null; refHost: string | null; utmSource: string | null; utmMedium: string | null; utmCampaign: string | null;
  ref: string | null; country: string | null; device: string | null; consent: string;
};
export type WebFilter = { src?: string | null; country?: string | null; device?: string | null };

export function applyWebFilter(rows: WebRow[], f: WebFilter): WebRow[] {
  return rows.filter((r) => (!f.src || r.src === f.src || (r.srcName ?? "") === f.src) && (!f.country || r.country === f.country) && (!f.device || r.device === f.device));
}

export type WebSummary = {
  views: number;
  landingViews: number;
  /** page views whose visitor had given analytics consent (ids exist for these) */
  consentedViews: number;
  /** share of page views with analytics consent; null with no views */
  consentRate: number | null;
  /** distinct anonymous ids (consented sample ONLY: never extrapolated) */
  visitors: number;
  newVisitors: number;
  returningVisitors: number;
  sessions: number;
  bouncedSessions: number;
  events: Record<WebEvent, number>;
};

const ZERO_EVENTS = (): Record<WebEvent, number> => ({ view: 0, scroll50: 0, scroll90: 0, prompt_focus: 0, prompt_submit: 0, plans_view: 0, signin_click: 0, signup_click: 0 });

export function webSummary(rows: WebRow[]): WebSummary {
  const events = ZERO_EVENTS();
  const vids = new Set<string>(), newVids = new Set<string>();
  const sess = new Map<string, { views: number; other: number }>();
  let landing = 0, consented = 0;
  for (const r of rows) {
    events[r.event]++;
    if (r.event === "view") {
      if (r.path === "/") landing++;
      if (r.consent === "analytics") consented++;
    }
    if (r.vid) { vids.add(r.vid); if (r.isNew && r.event === "view") newVids.add(r.vid); }
    if (r.sid) {
      const s = sess.get(r.sid) ?? { views: 0, other: 0 };
      if (r.event === "view") s.views++; else s.other++;
      sess.set(r.sid, s);
    }
  }
  const bounced = [...sess.values()].filter((s) => s.views === 1 && s.other === 0).length;
  return {
    views: events.view, landingViews: landing, consentedViews: consented, consentRate: ratio(consented, events.view),
    visitors: vids.size, newVisitors: newVids.size, returningVisitors: Math.max(0, vids.size - newVids.size),
    sessions: sess.size, bouncedSessions: bounced, events,
  };
}

export type CountRow = { key: string; n: number; share: number | null };
export function countBy(rows: WebRow[], pick: (r: WebRow) => string | null, event: WebEvent = "view", limit = 20): CountRow[] {
  const m = new Map<string, number>();
  let total = 0;
  for (const r of rows) {
    if (r.event !== event) continue;
    const k = pick(r);
    if (k === null || k === "") continue;
    m.set(k, (m.get(k) ?? 0) + 1);
    total++;
  }
  return [...m].map(([key, n]) => ({ key, n, share: ratio(n, total) })).sort((a, b) => b.n - a.n || a.key.localeCompare(b.key)).slice(0, limit);
}

export type SourceRow = { src: SourceClass; name: string; views: number; promptSubmits: number; signinClicks: number; share: number | null };
/** Sources with how far each got (page loads that reached prompt submit / a sign-in or sign-up click). */
export function sourceTable(rows: WebRow[]): SourceRow[] {
  const m = new Map<string, SourceRow>();
  let total = 0;
  for (const r of rows) {
    const key = `${r.src}|${r.srcName ?? ""}`;
    const cur = m.get(key) ?? { src: r.src, name: r.srcName ?? (r.src === "direct" ? "direct / none" : r.src), views: 0, promptSubmits: 0, signinClicks: 0, share: null };
    if (r.event === "view") { cur.views++; total++; }
    else if (r.event === "prompt_submit") cur.promptSubmits++;
    else if (r.event === "signin_click" || r.event === "signup_click") cur.signinClicks++;
    m.set(key, cur);
  }
  return [...m.values()].filter((s) => s.views || s.promptSubmits || s.signinClicks).map((s) => ({ ...s, share: ratio(s.views, total) })).sort((a, b) => b.views - a.views);
}

export type CampaignRow = { source: string; medium: string; campaign: string; views: number; promptSubmits: number; signinClicks: number };
export function campaignTable(rows: WebRow[]): CampaignRow[] {
  const m = new Map<string, CampaignRow>();
  for (const r of rows) {
    if (!r.utmSource && !r.utmMedium && !r.utmCampaign) continue;
    const key = `${r.utmSource ?? ""}|${r.utmMedium ?? ""}|${r.utmCampaign ?? ""}`;
    const cur = m.get(key) ?? { source: r.utmSource ?? "(none)", medium: r.utmMedium ?? "(none)", campaign: r.utmCampaign ?? "(none)", views: 0, promptSubmits: 0, signinClicks: 0 };
    if (r.event === "view") cur.views++;
    else if (r.event === "prompt_submit") cur.promptSubmits++;
    else if (r.event === "signin_click" || r.event === "signup_click") cur.signinClicks++;
    m.set(key, cur);
  }
  return [...m.values()].sort((a, b) => b.views - a.views);
}

export type WebFunnelStep = { id: string; label: string; n: number; ofFirst: number | null; ofPrev: number | null };
/**
 * The landing funnel in PAGE LOADS: each client sends each event at most once per page load, so an event count equals
 * the number of page loads that did it, whether or not the visitor is identifiable. A sign-in OR sign-up click counts
 * once per click event (a load with both counts twice: shown as "clicks", not people).
 */
export function webFunnel(rows: WebRow[]): WebFunnelStep[] {
  const landing = rows.filter((r) => r.path === "/");
  const c = ZERO_EVENTS();
  for (const r of landing) c[r.event]++;
  const steps: [string, string, number][] = [
    ["view", "Landing page loads", c.view],
    ["scroll50", "Scrolled 50%", c.scroll50],
    ["prompt_focus", "Clicked into the prompt box", c.prompt_focus],
    ["prompt_submit", "Submitted a prompt", c.prompt_submit],
    ["plans_view", "Saw the plans", c.plans_view],
    ["signin_click", "Clicked sign in or sign up", c.signin_click + c.signup_click],
  ];
  const first = steps[0][2];
  return steps.map(([id, label, n], i) => ({ id, label, n, ofFirst: ratio(n, first), ofPrev: i === 0 ? null : ratio(n, steps[i - 1][2]) }));
}

/** Median time between landing events inside one consented session (the only place a person is linkable). */
export function sessionStepMedians(rows: WebRow[]): { from: string; to: string; medianMs: number | null; n: number }[] {
  const by = new Map<string, Map<string, number>>();
  for (const r of rows) {
    if (!r.sid || r.path !== "/") continue;
    const s = by.get(r.sid) ?? new Map<string, number>();
    const prev = s.get(r.event);
    if (prev === undefined || r.at < prev) s.set(r.event, r.at);
    by.set(r.sid, s);
  }
  const pairs: [WebEvent, WebEvent][] = [["view", "prompt_focus"], ["prompt_focus", "prompt_submit"], ["prompt_submit", "signin_click"]];
  return pairs.map(([a, b]) => {
    const d: number[] = [];
    for (const s of by.values()) { const ta = s.get(a), tb = s.get(b); if (ta !== undefined && tb !== undefined && tb >= ta) d.push(tb - ta); }
    return { from: a, to: b, medianMs: median(d), n: d.length };
  });
}

export type DayPoint = { day: string; n: number };
/** One point per UTC day in [fromMs, toMs): zero-filled so charts never skip a day. */
export function perDay(timesMs: number[], fromMs: number, toMs: number): DayPoint[] {
  const start = utcDay(fromMs), end = utcDay(toMs - 1);
  const m = new Map<string, number>();
  for (const t of timesMs) if (t >= fromMs && t < toMs) m.set(dayKey(t), (m.get(dayKey(t)) ?? 0) + 1);
  const out: DayPoint[] = [];
  for (let d = start; d <= end; d += DAY) out.push({ day: dayKey(d), n: m.get(dayKey(d)) ?? 0 });
  return out;
}

// ===========================================================================
// ACCOUNTS (existing product facts)
// ===========================================================================

export type FlightVerdict = "passed" | "passed_with_warnings" | "failed" | "incomplete" | "not_run";
export type PlanTierId = "free" | "katara" | "saka" | "all";

export type BuildFact = {
  id: string; userId: string; at: number; status: string; errorCode: string | null; costUsd: number; durationMs: number | null;
  attempts: number; isRefine: boolean; model: string; lanes: string[]; flight: FlightVerdict | null; image: string | null;
  installedAt: number | null; finishedAt: number | null;
};

export type AccountFact = {
  userId: string;
  firstSeenAt: number;
  accountCreatedAt: number | null;
  verified: boolean | null;
  /** The Nxeon account was created within 24 h before the first Cyrus touch (null when the creation time is unknown). */
  newToNxeon: boolean | null;
  signInAt: number | null;
  usernameAt: number | null;
  firstPromptAt: number | null;
  planShownAt: number | null;
  firstBuildAt: number | null;
  firstSuccessAt: number | null;
  firstInstallAt: number | null;
  firstPaidAt: number | null;
  plan: PlanTierId;
  /** Source of the sign-up from the consented attribution snapshot (null = none stored). */
  source: { src: SourceClass; name: string | null; landing: string | null; ref: string | null } | null;
  consent: "analytics" | "none" | "unknown";
  /** staff or an owner-excluded test account: never counted */
  excluded: boolean;
};

export const finished = (b: Pick<BuildFact, "status">) => b.status === "succeeded" || b.status === "failed";
export const isSuccess = (b: Pick<BuildFact, "status">) => b.status === "succeeded";
/** A build the service finished on its first compile attempt (attempts counts compile tries; 0 = unknown, never counted). */
export const isFirstTry = (b: Pick<BuildFact, "status" | "attempts">) => b.status === "succeeded" && b.attempts === 1;

// ---- the account funnel -----------------------------------------------------

export const FUNNEL_STEPS = [
  { id: "signin", label: "First Cyrus sign-in" },
  { id: "username", label: "Username claimed" },
  { id: "first_build", label: "First build started" },
  { id: "first_success", label: "First successful build" },
  { id: "first_install", label: "First install on a server" },
  { id: "paid", label: "Paid (token purchase or plan)" },
] as const;
export type FunnelStepId = (typeof FUNNEL_STEPS)[number]["id"];

/** The timestamps of an account in FUNNEL_STEPS order (null = not reached / not recorded). */
export function stepTimes(a: AccountFact): (number | null)[] {
  return [a.signInAt ?? a.firstSeenAt, a.usernameAt, a.firstBuildAt, a.firstSuccessAt, a.firstInstallAt, a.firstPaidAt];
}

export type AccountFunnelStep = {
  id: FunnelStepId; label: string;
  /** accounts that reached this step or any LATER step (a skipped step does not drop a person out of the funnel) */
  reached: number;
  ofFirst: number | null; ofPrev: number | null;
  /** of `reached`: those with no timestamp at this step (they got further without it, e.g. no username claimed) */
  skipped: number;
  medianMsFromPrev: number | null; timedPairs: number;
  /** pairs where this step's time is BEFORE the previous step's (excluded from the median, shown honestly) */
  outOfOrder: number;
};

/**
 * Ordered account funnel. "Reached step k" = the account has a timestamp at step k or at any later step, so the counts never
 * rise down the funnel and a skipped step (no username) does not hide people. Medians use only accounts with BOTH adjacent
 * timestamps in order.
 */
export function accountFunnel(accounts: AccountFact[]): AccountFunnelStep[] {
  const times = accounts.map(stepTimes);
  const furthest = times.map((t) => { let f = -1; t.forEach((x, i) => { if (x !== null) f = i; }); return f; });
  const first = furthest.filter((f) => f >= 0).length;
  return FUNNEL_STEPS.map((s, k) => {
    const reached = furthest.filter((f) => f >= k).length;
    const prevReached = k === 0 ? reached : furthest.filter((f) => f >= k - 1).length;
    let skipped = 0;
    const deltas: number[] = [];
    let oo = 0;
    times.forEach((t, i) => {
      if (furthest[i] >= k && t[k] === null) skipped++;
      if (k > 0 && t[k] !== null && t[k - 1] !== null) {
        const d = (t[k] as number) - (t[k - 1] as number);
        if (d >= 0) deltas.push(d); else oo++;
      }
    });
    return { id: s.id, label: s.label, reached, ofFirst: ratio(reached, first), ofPrev: k === 0 ? null : ratio(reached, prevReached), skipped, medianMsFromPrev: median(deltas), timedPairs: deltas.length, outOfOrder: oo };
  });
}

// ---- cohorts ----------------------------------------------------------------

export type CohortRow = {
  week: string; size: number;
  /** Day-N retention: the share of ELIGIBLE accounts (a whole day N has passed) that built on day N since first seen */
  d1: RetentionCell; d7: RetentionCell; d30: RetentionCell;
  /** "still coming back": built on day N or any later day */
  d7plus: RetentionCell; d30plus: RetentionCell;
};
export type RetentionCell = { active: number; eligible: number; rate: number | null };

export function weeklyCohorts(accounts: AccountFact[], buildsByUser: Map<string, number[]>, nowMs: number, weeks = 12): CohortRow[] {
  const thisWeek = weekStart(nowMs);
  const groups = new Map<number, AccountFact[]>();
  for (const a of accounts) {
    const w = weekStart(a.firstSeenAt);
    if (w > thisWeek || w < thisWeek - (weeks - 1) * 7 * DAY) continue;
    const g = groups.get(w) ?? [];
    g.push(a);
    groups.set(w, g);
  }
  const cell = (members: AccountFact[], n: number, plus: boolean): RetentionCell => {
    let active = 0, eligible = 0;
    for (const a of members) {
      const origin = utcDay(a.firstSeenAt);
      if (nowMs < origin + (n + 1) * DAY) continue; // day n not over yet
      eligible++;
      const days = (buildsByUser.get(a.userId) ?? []).map((t) => Math.floor((utcDay(t) - origin) / DAY));
      if (plus ? days.some((d) => d >= n) : days.some((d) => d === n)) active++;
    }
    return { active, eligible, rate: ratio(active, eligible) };
  };
  return [...groups].sort((a, b) => b[0] - a[0]).map(([w, members]) => ({
    week: dayKey(w), size: members.length,
    d1: cell(members, 1, false), d7: cell(members, 7, false), d30: cell(members, 30, false),
    d7plus: cell(members, 7, true), d30plus: cell(members, 30, true),
  }));
}

// ---- product ----------------------------------------------------------------

export type LaneStat = { lane: string; builds: number; finished: number; succeeded: number; firstTry: number; successRate: number | null; firstTryRate: number | null; costUsd: number; costPerSuccess: number | null };
export function laneStats(builds: BuildFact[]): LaneStat[] {
  const m = new Map<string, LaneStat>();
  const add = (lane: string, b: BuildFact) => {
    const s = m.get(lane) ?? { lane, builds: 0, finished: 0, succeeded: 0, firstTry: 0, successRate: null, firstTryRate: null, costUsd: 0, costPerSuccess: null };
    s.builds++;
    if (finished(b)) s.finished++;
    if (isSuccess(b)) s.succeeded++;
    if (isFirstTry(b)) s.firstTry++;
    s.costUsd += b.costUsd;
    m.set(lane, s);
  };
  for (const b of builds) {
    if (!b.lanes.length) add("(no plan recorded)", b);
    else for (const l of b.lanes) add(l, b);
  }
  return [...m.values()].map((s) => ({ ...s, successRate: ratio(s.succeeded, s.finished), firstTryRate: ratio(s.firstTry, s.finished), costPerSuccess: ratio(s.costUsd, s.succeeded) })).sort((a, b) => b.builds - a.builds);
}

export type ImageStat = { image: string; succeeded: number; firstTry: number; firstTryShare: number | null };
/** Only SUCCEEDED builds carry an engine release record, so a per-image success rate cannot be computed: first-try share among successes can. */
export function imageStats(builds: BuildFact[]): { rows: ImageStat[]; withoutRelease: number } {
  const m = new Map<string, ImageStat>();
  let none = 0;
  for (const b of builds) {
    if (!isSuccess(b)) continue;
    if (!b.image) { none++; continue; }
    const s = m.get(b.image) ?? { image: b.image, succeeded: 0, firstTry: 0, firstTryShare: null };
    s.succeeded++;
    if (isFirstTry(b)) s.firstTry++;
    m.set(b.image, s);
  }
  return { rows: [...m.values()].map((s) => ({ ...s, firstTryShare: ratio(s.firstTry, s.succeeded) })).sort((a, b) => b.succeeded - a.succeeded), withoutRelease: none };
}

export type ProductSummary = {
  builds: number; finished: number; succeeded: number; failed: number; successRate: number | null; firstTryRate: number | null;
  activeUsers: number; promptsPerUserMean: number | null; promptsPerUserMedian: number | null;
  promptBuckets: { label: string; users: number }[];
  refineRate: number | null; refines: number;
  abandonedBuilds: number; abandonedRate: number | null;
  costUsd: number; costPerSuccess: number | null;
  medianBuildMs: number | null;
  timeToFirstSuccessMs: { median: number | null; n: number };
  topErrors: { code: string; n: number }[];
  flights: { passed: number; passedWithWarnings: number; failed: number; incomplete: number; notRun: number; none: number };
};

/** Failed or cancelled-style builds after which the same account made no other build within `graceMs` (and that grace has passed). */
export function abandonedBuilds(builds: BuildFact[], nowMs: number, graceMs = DAY): number {
  const byUser = new Map<string, number[]>();
  for (const b of builds) { const a = byUser.get(b.userId) ?? []; a.push(b.at); byUser.set(b.userId, a); }
  let n = 0;
  for (const b of builds) {
    if (b.status !== "failed" && b.status !== "cancelled") continue;
    if (nowMs - b.at < graceMs) continue;
    const again = (byUser.get(b.userId) ?? []).some((t) => t > b.at && t - b.at <= graceMs);
    if (!again) n++;
  }
  return n;
}

export function productSummary(builds: BuildFact[], accounts: AccountFact[], nowMs: number, sinceMs: number): ProductSummary {
  const inWin = builds.filter((b) => b.at >= sinceMs && b.at <= nowMs);
  const fin = inWin.filter(finished), ok = inWin.filter(isSuccess), bad = inWin.filter((b) => b.status === "failed");
  const per = new Map<string, number>();
  for (const b of inWin) per.set(b.userId, (per.get(b.userId) ?? 0) + 1);
  const counts = [...per.values()];
  const bucket = (lo: number, hi: number) => counts.filter((c) => c >= lo && c <= hi).length;
  const errs = new Map<string, number>();
  for (const b of bad) errs.set(b.errorCode || "unknown", (errs.get(b.errorCode || "unknown") ?? 0) + 1);
  const fl = { passed: 0, passedWithWarnings: 0, failed: 0, incomplete: 0, notRun: 0, none: 0 };
  for (const b of ok) {
    if (b.flight === "passed") fl.passed++; else if (b.flight === "passed_with_warnings") fl.passedWithWarnings++;
    else if (b.flight === "failed") fl.failed++; else if (b.flight === "incomplete") fl.incomplete++;
    else if (b.flight === "not_run") fl.notRun++; else fl.none++;
  }
  const refines = inWin.filter((b) => b.isRefine).length;
  const aband = abandonedBuilds(inWin, nowMs);
  const ttfs = accounts.filter((a) => a.firstBuildAt !== null && a.firstSuccessAt !== null && a.firstSuccessAt >= a.firstBuildAt && a.firstSeenAt >= sinceMs).map((a) => (a.firstSuccessAt as number) - (a.firstBuildAt as number));
  const cost = inWin.reduce((s, b) => s + (b.costUsd || 0), 0);
  return {
    builds: inWin.length, finished: fin.length, succeeded: ok.length, failed: bad.length,
    successRate: ratio(ok.length, fin.length), firstTryRate: ratio(ok.filter(isFirstTry).length, fin.length),
    activeUsers: per.size, promptsPerUserMean: mean(counts) === null ? null : r1(mean(counts) as number), promptsPerUserMedian: median(counts),
    promptBuckets: [{ label: "1", users: bucket(1, 1) }, { label: "2", users: bucket(2, 2) }, { label: "3 to 5", users: bucket(3, 5) }, { label: "6 to 10", users: bucket(6, 10) }, { label: "11 or more", users: bucket(11, 1e9) }],
    refineRate: ratio(refines, inWin.length), refines,
    abandonedBuilds: aband, abandonedRate: ratio(aband, bad.length),
    costUsd: cost, costPerSuccess: ratio(cost, ok.length),
    medianBuildMs: median(fin.map((b) => b.durationMs ?? NaN).filter((x) => x > 0)),
    timeToFirstSuccessMs: { median: median(ttfs), n: ttfs.length },
    topErrors: [...errs].map(([code, n]) => ({ code, n })).sort((a, b) => b.n - a.n).slice(0, 8),
    flights: fl,
  };
}

/** Plan screens shown with no build started by the same account within `windowMs`. */
export function planAbandonment(planShown: { userId: string; at: number }[], builds: BuildFact[], nowMs: number, windowMs = 30 * 60_000): { shown: number; accountsShown: number; noBuild: number; rate: number | null } {
  const byUser = new Map<string, number[]>();
  for (const b of builds) { const a = byUser.get(b.userId) ?? []; a.push(b.at); byUser.set(b.userId, a); }
  let counted = 0, none = 0;
  for (const p of planShown) {
    if (nowMs - p.at < windowMs) continue; // not decided yet
    counted++;
    if (!(byUser.get(p.userId) ?? []).some((t) => t >= p.at && t - p.at <= windowMs)) none++;
  }
  return { shown: planShown.length, accountsShown: new Set(planShown.map((p) => p.userId)).size, noBuild: none, rate: ratio(none, counted) };
}

// ---- money ------------------------------------------------------------------

export type LedgerFact = { userId: string; kind: string; source: string | null; delta: number; at: number; meta: unknown };
export type PlanFact = { userId: string; tier: string; status: string; livemode: boolean };
export type MoneyFees = { stripePct: number; stripeFixedCents: number };

const metaOf = (m: unknown): Record<string, unknown> => (m && typeof m === "object" && !Array.isArray(m) ? (m as Record<string, unknown>) : {});
const cents = (v: unknown) => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.round(v) : null);

export type MoneySummary = {
  topupCents: number; planCents: number; totalCents: number; purchases: number; payers: number; testCents: number; unknownAmount: number;
  tokensPurchased: number; tokensSpent: number; tokensGrantedFree: number;
  aiCostUsd: number; revenueMinusAiUsd: number; estCardFeesUsd: number; marginAfterFeesUsd: number;
  /** AI cost of builds by accounts that never paid (lifetime), and of paying accounts */
  aiCostNonPayersUsd: number; aiCostPayersUsd: number;
  mrr: { cents: number | null; subscriptions: number; withoutPaidInvoice: number };
  planMix: { tier: string; n: number }[];
  arppuCents: number | null;
};

/**
 * Honest money. Revenue = real (live-mode) payments recorded in the token ledger; test-mode money is counted apart. MRR is the
 * sum, over live active subscriptions, of the amount that account's LAST plan invoice really paid (not a list price); a
 * subscription with no recorded paid invoice is excluded and counted. Card fees are an ESTIMATE from the Economy settings.
 */
export function moneySummary(i: { ledger: LedgerFact[]; plans: PlanFact[]; builds: BuildFact[]; lifetimePayers: Set<string>; fees: MoneyFees; sinceMs: number; untilMs: number }): MoneySummary {
  const win = i.ledger.filter((l) => l.at >= i.sinceMs && l.at < i.untilMs);
  let topup = 0, plan = 0, test = 0, unknown = 0, purchases = 0, fees = 0, purchased = 0, spent = 0, granted = 0;
  const payers = new Set<string>();
  for (const l of win) {
    if (l.kind === "purchase") {
      const m = metaOf(l.meta);
      const paid = l.source === "plan" ? cents(m.amountPaid) : cents(m.paidCents);
      if (paid === null) { unknown++; continue; }
      if (m.livemode === false) { test += paid; continue; }
      purchases++; payers.add(l.userId); purchased += Math.max(0, l.delta);
      if (l.source === "plan") plan += paid; else topup += paid;
      fees += (paid * i.fees.stripePct) / 100 + i.fees.stripeFixedCents;
    } else if (l.kind === "spend") spent += Math.abs(l.delta);
    else if (l.kind === "grant") granted += Math.max(0, l.delta);
  }
  const wb = i.builds.filter((b) => b.at >= i.sinceMs && b.at < i.untilMs);
  const ai = wb.reduce((s, b) => s + (b.costUsd || 0), 0);
  const aiNon = wb.filter((b) => !i.lifetimePayers.has(b.userId)).reduce((s, b) => s + (b.costUsd || 0), 0);
  const total = topup + plan;
  // MRR from the last live plan invoice of each active live subscription (look at the whole ledger passed in)
  const lastPlanPaid = new Map<string, { at: number; cents: number }>();
  for (const l of i.ledger) {
    if (l.kind !== "purchase" || l.source !== "plan") continue;
    const m = metaOf(l.meta);
    const paid = cents(m.amountPaid);
    if (paid === null || m.livemode === false) continue;
    const cur = lastPlanPaid.get(l.userId);
    if (!cur || l.at > cur.at) lastPlanPaid.set(l.userId, { at: l.at, cents: paid });
  }
  const live = i.plans.filter((p) => p.livemode && p.status === "active");
  let mrr = 0, without = 0;
  for (const p of live) { const v = lastPlanPaid.get(p.userId); if (v) mrr += v.cents; else without++; }
  const mix = new Map<string, number>();
  for (const p of live) mix.set(p.tier, (mix.get(p.tier) ?? 0) + 1);
  const feeUsd = fees / 100;
  return {
    topupCents: topup, planCents: plan, totalCents: total, purchases, payers: payers.size, testCents: test, unknownAmount: unknown,
    tokensPurchased: purchased, tokensSpent: spent, tokensGrantedFree: granted,
    aiCostUsd: ai, revenueMinusAiUsd: total / 100 - ai, estCardFeesUsd: feeUsd, marginAfterFeesUsd: total / 100 - ai - feeUsd,
    aiCostNonPayersUsd: aiNon, aiCostPayersUsd: ai - aiNon,
    mrr: { cents: live.length - without > 0 ? mrr : null, subscriptions: live.length, withoutPaidInvoice: without },
    planMix: [...mix].map(([tier, n]) => ({ tier, n })).sort((a, b) => b.n - a.n),
    arppuCents: payers.size ? Math.round(total / payers.size) : null,
  };
}

// ---- acquisition from the consented attribution snapshot --------------------

/** Account source from a stored attribution (ref / utm / landing). No referrer host exists there, so AI assistants show only via utm_source. */
export function sourceOfAttribution(a: { ref?: string; utm?: { source?: string; medium?: string }; landing?: string } | null): AccountFact["source"] {
  if (!a || (!a.ref && !a.utm && !a.landing)) return null;
  const c = classifySource({ refHost: null, utmSource: a.utm?.source ?? null, utmMedium: a.utm?.medium ?? null });
  const src: SourceClass = a.ref && c.src === "direct" ? "referral" : c.src;
  return { src, name: c.srcName ?? (a.ref ? `partner:${a.ref}` : null), landing: a.landing ?? null, ref: a.ref ?? null };
}

export type SourceAccounts = { key: string; accounts: number; built: number; succeeded: number; paid: number };
export function accountsBySource(accounts: AccountFact[]): SourceAccounts[] {
  const m = new Map<string, SourceAccounts>();
  for (const a of accounts) {
    const key = a.source ? (a.source.name ? `${a.source.src}: ${a.source.name}` : a.source.src) : "unknown (no consented attribution)";
    const s = m.get(key) ?? { key, accounts: 0, built: 0, succeeded: 0, paid: 0 };
    s.accounts++;
    if (a.firstBuildAt !== null) s.built++;
    if (a.firstSuccessAt !== null) s.succeeded++;
    if (a.firstPaidAt !== null) s.paid++;
    m.set(key, s);
  }
  return [...m.values()].sort((a, b) => b.accounts - a.accounts);
}

// ---- CSV --------------------------------------------------------------------

/** One CSV cell, safe for spreadsheets: a leading = + - @ tab or CR is neutralised, quotes/commas/newlines escaped. */
export function csvCell(v: unknown): string {
  let s = v === null || v === undefined ? "" : typeof v === "number" ? (Number.isFinite(v) ? String(v) : "") : String(v);
  if (/^[=+\-@\t\r]/.test(s) && !(typeof v === "number")) s = "'" + s;
  if (/[",\n\r]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}
export function toCsv(headers: string[], rows: unknown[][]): string {
  return [headers.map(csvCell).join(","), ...rows.map((r) => r.map(csvCell).join(","))].join("\n") + "\n";
}

