// Cyrus analytics WRITERS (server only), through cyrusDb (the host seam). Everything is best effort: a missing table (the
// db push is pending) or a database hiccup never reaches the page the visitor is on. Collection is behind CYRUS_ANALYTICS=1
// (off = nothing is written; the admin page still reads the facts that already exist).
import { randomUUID } from "node:crypto";
import { cyrusDb } from "../db";
import type { CleanWebRow } from "./web";
import { RAW_RETENTION_DAYS } from "./web";

type Env = Record<string, string | undefined>;
export const analyticsEnabled = (env: Env = process.env) => env.CYRUS_ANALYTICS === "1";

const DAY = 86_400_000;
const utcDay = (ms: number) => Math.floor(ms / DAY) * DAY;

/** Store one human web event. Returns true when a row was written. Never throws. */
export async function recordWebRow(row: CleanWebRow): Promise<boolean> {
  try {
    await cyrusDb.cyrusWebEvent.create({ data: { ...row } });
    return true;
  } catch {
    return false;
  }
}

// Bot hits are only COUNTED (CyrusDailyMetrics key web.bot_hits, dim kind=<botKind>), batched in memory so a crawler storm
// is one write per few seconds, not one per hit. A restart loses at most the last few seconds of counts.
const botBuf = new Map<string, number>();
let botLast = Date.now();
const BOT_FLUSH_MS = 10_000;

export function bufferBotHit(botKind: string, now = Date.now()): void {
  const k = `${utcDay(now)}|kind=${botKind.replace(/[^a-z-]/g, "").slice(0, 30) || "bot"}`;
  botBuf.set(k, (botBuf.get(k) ?? 0) + 1);
  if (now - botLast >= BOT_FLUSH_MS) void flushBotHits(now);
}

export async function flushBotHits(now = Date.now()): Promise<number> {
  botLast = now;
  if (!botBuf.size) return 0;
  const batch = [...botBuf];
  botBuf.clear();
  let n = 0;
  for (const [k, v] of batch) {
    const [day, dim] = k.split("|");
    try {
      await cyrusDb.$executeRaw`INSERT INTO "CyrusDailyMetrics" ("id","date","key","dim","value","updatedAt") VALUES (${randomUUID()}, ${new Date(Number(day))}, ${"web.bot_hits"}, ${dim}, ${v}, NOW()) ON CONFLICT ("date","key","dim") DO UPDATE SET "value" = "CyrusDailyMetrics"."value" + ${v}, "updatedAt" = NOW()`;
      n += v;
    } catch { /* table missing or hiccup: counters are best effort */ }
  }
  return n;
}

/** Delete raw web events past the retention window (aggregates are kept). Batched; returns rows deleted. */
export async function purgeRawEvents(now = Date.now(), days = RAW_RETENTION_DAYS): Promise<number> {
  const cutoff = new Date(now - days * DAY);
  let total = 0;
  for (let i = 0; i < 40; i++) {
    try {
      const n = await cyrusDb.$executeRaw`DELETE FROM "CyrusWebEvent" WHERE "id" IN (SELECT "id" FROM "CyrusWebEvent" WHERE "at" < ${cutoff} LIMIT 5000)`;
      total += Number(n);
      if (Number(n) < 5000) break;
    } catch { break; }
  }
  return total;
}

// ---------------------------------------------------------------------------
// The one product event with no other fact: plan_shown
// ---------------------------------------------------------------------------

export const PRODUCT_EVENT_KINDS = ["plan_shown"] as const;
export type ProductEventKind = (typeof PRODUCT_EVENT_KINDS)[number];

/** Dedupe key: one event per account per kind per 10 minutes (a plan screen re-rendered while typing is one plan). */
export const productEventKey = (kind: ProductEventKind, userId: string, nowMs: number) => `${kind}:${userId}:${Math.floor(nowMs / 600_000)}`.slice(0, 120);

export function productEventRow(i: { kind: ProductEventKind; userId: string; game?: string | null; mcVersion?: string | null; change?: boolean; now?: number }) {
  const now = i.now ?? Date.now();
  return {
    userId: String(i.userId).slice(0, 64), kind: i.kind, key: productEventKey(i.kind, i.userId, now),
    // never the prompt, never an email: the game, the Minecraft version and whether it was a change request
    meta: { game: String(i.game ?? "minecraft").replace(/[^a-z0-9_-]/gi, "").slice(0, 20), mcVersion: String(i.mcVersion ?? "").replace(/[^0-9a-z._-]/gi, "").slice(0, 20), change: i.change === true },
    at: new Date(now),
  };
}

/** Record that the plan screen answered for an account. Fire-and-forget; never throws; inert unless CYRUS_ANALYTICS=1. */
export async function recordProductEvent(i: Parameters<typeof productEventRow>[0], env: Env = process.env): Promise<boolean> {
  if (!analyticsEnabled(env) || !i.userId) return false;
  try {
    await cyrusDb.cyrusProductEvent.create({ data: productEventRow(i) });
    return true;
  } catch {
    return false; // duplicate key (same 10 minutes), table missing, or a hiccup
  }
}

