// Cyrus analytics LOADER (server only): turns the rows Cyrus already writes (ModBuild, the token ledger, plans, creators,
// attribution snapshots, community tables) plus the few platform facts behind host.analytics into the plain fact types
// ./metrics.ts computes on. NO new write path is needed for any of these (only plan_shown and the web beacon write).
// Reads are bounded (`take` caps; a cap hit is reported as `truncated`), every table read is tolerant of "table not created
// yet" (the page then says so), and nothing personal leaves this file: emails stay in the host, prompts are never selected.
import { cyrusDb } from "../db";
import { getHost } from "../host";
import type { HostCyrusVisit } from "../host/types";
import { readCyrusMeta } from "../meta";
import { readStoredFlight } from "../testflight/gate";
import { parseEconFees, ECON_SETTINGS } from "../admin/economy";
import { decodeAttribution, parseConsent } from "./consent";
import { DAY, sourceOfAttribution, utcDay, type AccountFact, type BuildFact, type FlightVerdict, type LedgerFact, type MoneyFees, type PlanFact, type PlanTierId, type WebRow } from "./metrics";
import type { SourceClass, WebEvent } from "./web";

export const EXCLUDE_SETTING = "cyrus_analytics_exclude_users";
const COHORT_DAYS = 84;
const CAP = { builds: 30000, web: 200000, ledger: 100000, visits: 20000, accounts: 50000 };

export type TableState = { web: boolean; daily: boolean; product: boolean; visits: boolean; hostAnalytics: boolean };

export type AnalyticsData = {
  now: number; days: number; from: number; lookbackFrom: number;
  web: WebRow[]; webTruncated: boolean; latestWebAt: number | null;
  botHits: { day: string; kind: string; n: number }[];
  platformVisits: HostCyrusVisit[];
  accounts: AccountFact[]; excluded: number;
  builds: BuildFact[]; buildsTruncated: boolean;
  buildTimesByUser: Map<string, number[]>;
  ledger: LedgerFact[]; plans: PlanFact[]; lifetimePayers: Set<string>;
  planShown: { userId: string; at: number }[];
  community: { published: number; librarySaves: number; forks: number; libraryUses: number };
  fees: MoneyFees;
  attributionRows: number;
  tables: TableState;
};

const tryQ = async <T>(f: () => Promise<T>, fallback: T, onFail?: () => void): Promise<T> => { try { return await f(); } catch { onFail?.(); return fallback; } };
const chunk = <T>(xs: T[], n: number): T[][] => { const o: T[][] = []; for (let i = 0; i < xs.length; i += n) o.push(xs.slice(i, i + n)); return o; };
const ms = (d: Date | string | null | undefined): number | null => { if (!d) return null; const t = d instanceof Date ? d.getTime() : Date.parse(d); return Number.isFinite(t) ? t : null; };

/** A stored ModBuild row -> the fact the maths uses. The prompt, the result JSON and every artefact stay unselected. */
export function buildFactOf(r: { id: string; userId: string; status: string; errorCode: string | null; attempts: number; costUsd: number | null; durationMs: number | null; createdAt: Date; finishedAt: Date | null; baseBuildId: string | null; cyrus: unknown; lastInstall: unknown }): BuildFact {
  const meta = readCyrusMeta(r.cyrus);
  const flight = readStoredFlight(meta.testFlight);
  const verdict: FlightVerdict | null = flight && flight.state !== "queued" && flight.state !== "running" ? (flight.verdict as FlightVerdict) : null;
  const rel = (meta.engineRelease ?? {}) as Record<string, unknown>;
  const svc = rel.service && typeof rel.service === "object" ? (rel.service as Record<string, unknown>) : {};
  const image = typeof svc.image === "string" && svc.image ? svc.image.slice(0, 60) : typeof rel.id === "string" ? `engine ${rel.id.slice(0, 10)}` : null;
  const li = r.lastInstall && typeof r.lastInstall === "object" && !Array.isArray(r.lastInstall) ? (r.lastInstall as { at?: unknown }) : null;
  const created = r.createdAt.getTime();
  return {
    id: r.id, userId: r.userId, at: created, status: r.status, errorCode: r.errorCode, costUsd: r.costUsd || 0, durationMs: r.durationMs,
    attempts: r.attempts || 0, isRefine: !!r.baseBuildId, model: meta.model ?? "auto", lanes: meta.assets?.planned?.lanes ?? [],
    flight: verdict, image, installedAt: typeof li?.at === "string" ? ms(li.at) : null,
    finishedAt: ms(r.finishedAt) ?? (r.durationMs ? created + r.durationMs : null),
  };
}

const tierOf = (t: string): PlanTierId => (t === "katara" || t === "saka" || t === "all" ? t : "free");

export async function loadAnalytics(days: number, now = Date.now()): Promise<AnalyticsData> {
  const host = getHost();
  const from = now - days * DAY;
  const lookbackFrom = now - Math.max(days, COHORT_DAYS) * DAY;
  const tables: TableState = { web: true, daily: true, product: true, visits: true, hostAnalytics: !!host.analytics };

  // ---- builds (light select: no prompt, no result) ----
  const buildRows = await tryQ(() => cyrusDb.modBuild.findMany({
    where: { createdAt: { gte: new Date(lookbackFrom) } }, orderBy: { createdAt: "desc" }, take: CAP.builds,
    select: { id: true, userId: true, status: true, errorCode: true, attempts: true, costUsd: true, durationMs: true, createdAt: true, finishedAt: true, baseBuildId: true, cyrus: true, lastInstall: true },
  }), []);
  const builds = buildRows.map(buildFactOf);
  const buildTimesByUser = new Map<string, number[]>();
  for (const b of builds) { const a = buildTimesByUser.get(b.userId) ?? []; a.push(b.at); buildTimesByUser.set(b.userId, a); }

  // ---- who and when ----
  const signIns = host.analytics ? await tryQ(() => host.analytics!.firstCyrusSignIns(lookbackFrom, CAP.accounts), []) : [];
  const buildUsers = [...buildTimesByUser.keys()];
  const tokenNew = await tryQ(() => cyrusDb.cyrusTokenAccount.findMany({ where: { createdAt: { gte: new Date(lookbackFrom) } }, select: { userId: true, createdAt: true }, take: CAP.accounts }), []);
  const creatorsNew = await tryQ(() => cyrusDb.cyrusCreator.findMany({ where: { createdAt: { gte: new Date(lookbackFrom) } }, select: { userId: true, createdAt: true }, take: CAP.accounts }), []);
  const universe = new Set<string>([...buildUsers, ...signIns.map((s) => s.userId), ...tokenNew.map((t) => t.userId), ...creatorsNew.map((c) => c.userId)]);
  const ids = [...universe].slice(0, CAP.accounts);

  const firstBuildAll = new Map<string, number>();
  const tokenAcct = new Map<string, number>();
  const creatorAt = new Map<string, number>();
  for (const part of chunk(ids, 1000)) {
    const [g, ta, cr] = await Promise.all([
      tryQ(() => cyrusDb.modBuild.groupBy({ by: ["userId"], where: { userId: { in: part } }, _min: { createdAt: true } }), []),
      tryQ(() => cyrusDb.cyrusTokenAccount.findMany({ where: { userId: { in: part } }, select: { userId: true, createdAt: true } }), []),
      tryQ(() => cyrusDb.cyrusCreator.findMany({ where: { userId: { in: part } }, select: { userId: true, createdAt: true } }), []),
    ]);
    for (const r of g) if (r._min.createdAt) firstBuildAll.set(r.userId, r._min.createdAt.getTime());
    for (const r of ta) tokenAcct.set(r.userId, r.createdAt.getTime());
    for (const r of cr) creatorAt.set(r.userId, r.createdAt.getTime());
  }
  const acc = host.analytics ? await tryQ(async () => { const o: Awaited<ReturnType<NonNullable<typeof host.analytics>["accounts"]>> = []; for (const part of chunk(ids, 1000)) o.push(...(await host.analytics!.accounts(part))); return o; }, []) : [];
  const accById = new Map(acc.map((a) => [a.id, a]));
  const signInBy = new Map(signIns.map((s) => [s.userId, s.at.getTime()]));

  // ---- exclusions: staff + the owner's list ----
  const excludeEmails = (await tryQ(() => host.settings.get(EXCLUDE_SETTING, ""), "")).split(/[,\s;]+/).map((e) => e.trim().toLowerCase()).filter(Boolean).slice(0, 50);
  const excludedIds = new Set<string>();
  for (const e of excludeEmails) { const u = await tryQ(() => host.users.find(e), null); if (u) excludedIds.add(u.id); }

  // ---- money facts ----
  const ledgerRows = await tryQ(() => cyrusDb.cyrusTokenLedger.findMany({
    where: { createdAt: { gte: new Date(lookbackFrom) }, kind: { in: ["purchase", "spend", "grant"] } }, orderBy: { createdAt: "desc" }, take: CAP.ledger,
    select: { userId: true, kind: true, source: true, delta: true, createdAt: true, meta: true },
  }), []);
  const ledger: LedgerFact[] = ledgerRows.map((l) => ({ userId: l.userId, kind: l.kind, source: l.source, delta: l.delta, at: l.createdAt.getTime(), meta: l.meta }));
  const payRows = await tryQ(() => cyrusDb.cyrusTokenLedger.findMany({ where: { kind: "purchase" }, select: { userId: true, createdAt: true, source: true, meta: true }, take: 50000 }), []);
  const firstPaid = new Map<string, number>();
  const lifetimePayers = new Set<string>();
  for (const p of payRows) {
    const m = (p.meta && typeof p.meta === "object" && !Array.isArray(p.meta) ? p.meta : {}) as Record<string, unknown>;
    const paid = p.source === "plan" ? m.amountPaid : m.paidCents;
    if (typeof paid !== "number" || paid <= 0 || m.livemode === false) continue; // grants/test mode are not payment
    lifetimePayers.add(p.userId);
    const t = p.createdAt.getTime();
    if (!firstPaid.has(p.userId) || t < (firstPaid.get(p.userId) as number)) firstPaid.set(p.userId, t);
  }
  const planRows = await tryQ(() => cyrusDb.cyrusPlan.findMany({ select: { userId: true, tier: true, status: true, livemode: true }, take: 20000 }), []);
  const plans: PlanFact[] = planRows.map((p) => ({ userId: p.userId, tier: p.tier, status: p.status, livemode: p.livemode }));
  const planOf = new Map<string, PlanTierId>();
  for (const p of plans) if (p.livemode && p.status === "active") planOf.set(p.userId, tierOf(p.tier));

  // ---- plan_shown + attribution ----
  const planEv = await tryQ(() => cyrusDb.cyrusProductEvent.findMany({ where: { kind: "plan_shown", at: { gte: new Date(lookbackFrom) } }, select: { userId: true, at: true }, orderBy: { at: "asc" }, take: 50000 }), [], () => { tables.product = false; });
  const planShown = planEv.map((e) => ({ userId: e.userId, at: e.at.getTime() }));
  const firstPlanShown = new Map<string, number>();
  for (const p of planShown) if (!firstPlanShown.has(p.userId)) firstPlanShown.set(p.userId, p.at);
  const attrRows = ids.length ? await tryQ(async () => { const o: { userId: string; consent: string; attr: string | null }[] = []; for (const part of chunk(ids, 1000)) o.push(...(await cyrusDb.cyrusAttribution.findMany({ where: { userId: { in: part } }, select: { userId: true, consent: true, attr: true } }))); return o; }, []) : [];
  const attrBy = new Map(attrRows.map((a) => [a.userId, a]));

  // ---- first success / install per account from the builds fetched ----
  const firstSuccess = new Map<string, number>();
  const firstInstall = new Map<string, number>();
  for (const b of builds) {
    if (b.status === "succeeded") { const t = b.finishedAt ?? b.at; if (!firstSuccess.has(b.userId) || t < (firstSuccess.get(b.userId) as number)) firstSuccess.set(b.userId, t); }
    if (b.installedAt !== null && (!firstInstall.has(b.userId) || b.installedAt < (firstInstall.get(b.userId) as number))) firstInstall.set(b.userId, b.installedAt);
  }

  // ---- account facts ----
  const accounts: AccountFact[] = [];
  let excluded = 0;
  for (const id of ids) {
    const a = accById.get(id);
    const times = [signInBy.get(id), tokenAcct.get(id), creatorAt.get(id), firstBuildAll.get(id), firstPlanShown.get(id)].filter((x): x is number => typeof x === "number");
    if (!times.length) continue;
    const firstSeen = Math.min(...times);
    if ((a && a.staff) || excludedIds.has(id)) { excluded++; continue; }
    const att = attrBy.get(id);
    const consent = att ? parseConsent(att.consent) : null;
    const attr = att ? decodeAttribution(att.attr) : null;
    const firstBuild = firstBuildAll.get(id) ?? null;
    const prompt = [firstBuild, firstPlanShown.get(id) ?? null].filter((x): x is number => x !== null);
    const created = a ? a.createdAt.getTime() : null;
    accounts.push({
      userId: id, firstSeenAt: firstSeen, accountCreatedAt: created, verified: a ? a.verified : null,
      newToNxeon: created === null ? null : firstSeen - created <= DAY && firstSeen >= created - 60_000,
      signInAt: signInBy.get(id) ?? null, usernameAt: creatorAt.get(id) ?? null,
      firstPromptAt: prompt.length ? Math.min(...prompt) : null, planShownAt: firstPlanShown.get(id) ?? null,
      firstBuildAt: firstBuild, firstSuccessAt: firstSuccess.get(id) ?? null, firstInstallAt: firstInstall.get(id) ?? null, firstPaidAt: firstPaid.get(id) ?? null,
      plan: planOf.get(id) ?? "free", source: sourceOfAttribution(attr),
      consent: consent ? (consent.analytics ? "analytics" : "none") : "unknown", excluded: false,
    });
  }
  const keepIds = new Set(accounts.map((a) => a.userId));

  // ---- web events (human only are stored), bot counters, platform visits ----
  const webRows = await tryQ(() => cyrusDb.cyrusWebEvent.findMany({
    where: { at: { gte: new Date(from) } }, orderBy: { at: "desc" }, take: CAP.web,
    select: { at: true, event: true, path: true, vid: true, sid: true, isNew: true, src: true, srcName: true, refHost: true, utmSource: true, utmMedium: true, utmCampaign: true, ref: true, country: true, device: true, consent: true },
  }), [], () => { tables.web = false; });
  const web: WebRow[] = webRows.map((r) => ({ ...r, at: r.at.getTime(), event: r.event as WebEvent, src: r.src as SourceClass }));
  const botRows = await tryQ(() => cyrusDb.cyrusDailyMetrics.findMany({ where: { key: "web.bot_hits", date: { gte: new Date(utcDay(from)) } }, select: { date: true, dim: true, value: true } }), [], () => { tables.daily = false; });
  const botHits = botRows.map((r) => ({ day: r.date.toISOString().slice(0, 10), kind: r.dim.replace(/^kind=/, "") || "bot", n: Math.round(r.value) }));
  const platformVisits = host.analytics ? await tryQ(() => host.analytics!.cyrusVisits({ sinceMs: from, untilMs: now + 1, limit: CAP.visits }), []) : [];

  // ---- community facts (counts only) ----
  const since = new Date(from);
  const [published, librarySaves, forks, libraryUses] = await Promise.all([
    tryQ(() => cyrusDb.cyrusModPage.count({ where: { publishedAt: { gte: since }, visibility: "PUBLIC", hiddenAt: null } }), 0),
    tryQ(() => cyrusDb.cyrusLibraryItem.count({ where: { createdAt: { gte: since } } }), 0),
    tryQ(() => cyrusDb.cyrusFork.count({ where: { createdAt: { gte: since } } }), 0),
    tryQ(() => cyrusDb.cyrusLibraryUse.count({ where: { createdAt: { gte: since } } }), 0),
  ]);

  const feeStored = await tryQ(() => host.settings.readStored([ECON_SETTINGS.stripePct, ECON_SETTINGS.stripeFixedCents]), {} as Record<string, string>);
  const fees = parseEconFees(feeStored);

  return {
    now, days, from, lookbackFrom,
    web, webTruncated: webRows.length >= CAP.web, latestWebAt: web.length ? Math.max(...web.map((w) => w.at)) : null,
    botHits, platformVisits,
    accounts, excluded,
    builds: builds.filter((b) => keepIds.has(b.userId)), buildsTruncated: buildRows.length >= CAP.builds,
    buildTimesByUser,
    ledger: ledger.filter((l) => keepIds.has(l.userId) || !universe.has(l.userId)), plans: plans.filter((p) => !excludedIds.has(p.userId)), lifetimePayers,
    planShown: planShown.filter((p) => keepIds.has(p.userId)),
    community: { published, librarySaves, forks, libraryUses },
    fees: { stripePct: fees.stripePct, stripeFixedCents: fees.stripeFixedCents },
    attributionRows: attrRows.length,
    tables,
  };
}

// ---------------------------------------------------------------------------
// Filters (pure)
// ---------------------------------------------------------------------------

export type AccountFilter = { plan?: string | null; src?: string | null };
export function filterAccounts(accts: AccountFact[], f: AccountFilter): AccountFact[] {
  return accts.filter((a) => (!f.plan || a.plan === f.plan) && (!f.src || (f.src === "unknown" ? a.source === null : a.source?.src === f.src || a.source?.name === f.src)));
}

