// Cyrus analytics REPORT MODEL (pure): loaded facts + filters in, every number the admin page, the JSON endpoint, the CSV
// export, the weekly digest and the nightly rollup show, out. One computation, so the page and the exports cannot disagree.
import type { AnalyticsData, AccountFilter } from "./facts";
import { filterAccounts } from "./facts";
import {
  DAY, accountFunnel, accountsBySource, applyWebFilter, campaignTable, countBy, dayKey, median, moneySummary, perDay, planAbandonment,
  productSummary, ratio, sessionStepMedians, sourceTable, webFunnel, webSummary, weeklyCohorts, laneStats, imageStats, utcDay,
  type AccountFact, type AccountFunnelStep, type BuildFact, type CohortRow, type CountRow, type CampaignRow, type DayPoint, type LaneStat,
  type MoneySummary, type ProductSummary, type SourceAccounts, type SourceRow, type WebFilter, type WebFunnelStep, type WebRow, type WebSummary, type ImageStat,
} from "./metrics";
import { isHumanHit } from "./web";

export type ReportFilters = WebFilter & AccountFilter;

export type Report = {
  generatedAt: number; days: number; from: number; to: number; filters: ReportFilters;
  web: {
    summary: WebSummary;
    bots: { hits: number; byKind: { kind: string; n: number }[]; humanViews: number; share: number | null };
    viewsPerDay: DayPoint[];
    sources: SourceRow[]; aiAssistants: SourceRow[];
    referrers: CountRow[]; pages: CountRow[]; campaigns: CampaignRow[]; countries: CountRow[]; devices: CountRow[];
    newVsReturning: { newVisitors: number; returningVisitors: number; consentedVisitors: number };
    funnel: WebFunnelStep[]; stepMedians: ReturnType<typeof sessionStepMedians>;
    platform: { views: number; humanViews: number; signedIn: number; topPaths: CountRow[]; searchOrAi: number };
  };
  accounts: {
    inWindow: number; newToNxeon: number; existingNxeon: number; unknownOrigin: number;
    activated: number; installed: number; paying: number; verifiedShare: number | null;
    funnel: AccountFunnelStep[]; bySource: SourceAccounts[]; cohorts: CohortRow[]; firstSeenPerDay: DayPoint[];
    northStar: { installedAccounts: number; medianMsFirstSeenToInstall: number | null; n: number; withinDayShare: number | null };
  };
  product: ProductSummary & { lanes: LaneStat[]; images: ImageStat[]; imagesWithoutRelease: number; plan: ReturnType<typeof planAbandonment>; buildsPerDay: DayPoint[]; byModel: { model: string; builds: number; succeeded: number; costUsd: number }[] };
  money: MoneySummary & { revenuePerDay: { day: string; cents: number }[] };
  community: AnalyticsData["community"];
  quality: {
    consentRate: number | null; botShare: number | null; webRows: number; webTruncated: boolean; buildsTruncated: boolean; accountsConsented: number; accountsWithAttribution: number;
    accountsTotal: number; excludedAccounts: number; latestWebAt: number | null; planEventsSince: number | null;
    tables: AnalyticsData["tables"];
  };
};

const isAi = (s: SourceRow) => s.src === "ai";

export function buildReport(d: AnalyticsData, filters: ReportFilters = {}, humanOnly = true): Report {
  const to = d.now;
  // ---- web ----
  const webAll: WebRow[] = d.web.filter((r) => r.at >= d.from && r.at <= to);
  const web = applyWebFilter(webAll, filters);
  const ws = webSummary(web);
  const botTotal = d.botHits.reduce((s, b) => s + b.n, 0);
  const byKind = new Map<string, number>();
  for (const b of d.botHits) byKind.set(b.kind, (byKind.get(b.kind) ?? 0) + b.n);
  const sources = sourceTable(web);
  const pv = d.platformVisits;
  const pvHuman = pv.filter((v) => isHumanHit(v));
  const pvPaths = new Map<string, number>();
  for (const v of pvHuman) { const p = v.path.split(/[?#]/)[0].slice(0, 80); pvPaths.set(p, (pvPaths.get(p) ?? 0) + 1); }
  const searchOrAi = pvHuman.filter((v) => v.referrer && /google\.|bing\.|duckduckgo\.|chatgpt\.com|openai\.com|perplexity\.ai|claude\.ai|gemini\.google/i.test(v.referrer)).length;
  const humanViews = webAll.filter((r) => r.event === "view").length;

  // ---- accounts ----
  const acctsAll = d.accounts;
  const acctsF = filterAccounts(acctsAll, filters);
  const inWin = acctsF.filter((a) => a.firstSeenAt >= d.from);
  const userSet = new Set(acctsF.map((a) => a.userId));
  const anyAcctFilter = !!(filters.plan || filters.src);
  const builds: BuildFact[] = anyAcctFilter ? d.builds.filter((b) => userSet.has(b.userId)) : d.builds;
  const winBuilds = builds.filter((b) => b.at >= d.from && b.at <= to);
  const installDeltas = inWin.filter((a) => a.firstInstallAt !== null && (a.firstInstallAt as number) >= a.firstSeenAt).map((a) => (a.firstInstallAt as number) - a.firstSeenAt);
  const paying = acctsF.filter((a) => a.firstPaidAt !== null && (a.firstPaidAt as number) >= d.from).length;
  const verified = inWin.filter((a) => a.verified !== null);

  // ---- product ----
  const ps = productSummary(builds, acctsF, to, d.from);
  const img = imageStats(winBuilds);
  const byModel = new Map<string, { model: string; builds: number; succeeded: number; costUsd: number }>();
  for (const b of winBuilds) {
    const m = byModel.get(b.model) ?? { model: b.model, builds: 0, succeeded: 0, costUsd: 0 };
    m.builds++; if (b.status === "succeeded") m.succeeded++; m.costUsd += b.costUsd;
    byModel.set(b.model, m);
  }

  // ---- money (restricted to the filtered accounts when a plan/source filter is set) ----
  const ledger = anyAcctFilter ? d.ledger.filter((l) => userSet.has(l.userId)) : d.ledger;
  const money = moneySummary({ ledger, plans: d.plans.filter((p) => !anyAcctFilter || userSet.has(p.userId)), builds, lifetimePayers: d.lifetimePayers, fees: d.fees, sinceMs: d.from, untilMs: to + 1 });
  const revByDay = new Map<string, number>();
  for (const l of ledger) {
    if (l.kind !== "purchase" || l.at < d.from || l.at > to) continue;
    const m = (l.meta && typeof l.meta === "object" && !Array.isArray(l.meta) ? l.meta : {}) as Record<string, unknown>;
    const paid = l.source === "plan" ? m.amountPaid : m.paidCents;
    if (typeof paid !== "number" || paid <= 0 || m.livemode === false) continue;
    revByDay.set(dayKey(l.at), (revByDay.get(dayKey(l.at)) ?? 0) + Math.round(paid));
  }
  const revenuePerDay: { day: string; cents: number }[] = [];
  for (let t = utcDay(d.from); t <= utcDay(to); t += DAY) revenuePerDay.push({ day: dayKey(t), cents: revByDay.get(dayKey(t)) ?? 0 });

  const planEv = d.planShown.filter((p) => !anyAcctFilter || userSet.has(p.userId)).filter((p) => p.at >= d.from);
  const consented = acctsAll.filter((a) => a.consent === "analytics").length;
  const withAttr = acctsAll.filter((a) => a.source !== null).length;
  const firstPlanEvent = d.planShown.length ? Math.min(...d.planShown.map((p) => p.at)) : null;

  const topCountries = countBy(web, (r) => r.country);
  return {
    generatedAt: d.now, days: d.days, from: d.from, to, filters,
    web: {
      summary: ws,
      bots: { hits: botTotal, byKind: [...byKind].map(([kind, n]) => ({ kind, n })).sort((a, b) => b.n - a.n), humanViews, share: humanOnly ? ratio(botTotal, botTotal + humanViews) : ratio(botTotal, botTotal + humanViews) },
      viewsPerDay: perDay(web.filter((r) => r.event === "view").map((r) => r.at), d.from, to + 1),
      sources, aiAssistants: sources.filter(isAi),
      referrers: countBy(web, (r) => r.refHost), pages: countBy(web, (r) => r.path), campaigns: campaignTable(web),
      countries: topCountries, devices: countBy(web, (r) => r.device),
      newVsReturning: { newVisitors: ws.newVisitors, returningVisitors: ws.returningVisitors, consentedVisitors: ws.visitors },
      funnel: webFunnel(web), stepMedians: sessionStepMedians(web),
      platform: { views: pv.length, humanViews: pvHuman.length, signedIn: pvHuman.filter((v) => v.signedIn).length, topPaths: [...pvPaths].map(([key, n]) => ({ key, n, share: ratio(n, pvHuman.length) })).sort((a, b) => b.n - a.n).slice(0, 15), searchOrAi },
    },
    accounts: {
      inWindow: inWin.length, newToNxeon: inWin.filter((a) => a.newToNxeon === true).length, existingNxeon: inWin.filter((a) => a.newToNxeon === false).length,
