  put("acct.first_build", at((a) => a.firstBuildAt));
  put("acct.first_success", at((a) => a.firstSuccessAt));
  put("acct.first_install", at((a) => a.firstInstallAt));
  put("acct.first_paid", at((a) => a.firstPaidAt));
  put("product.plan_shown", d.planShown.filter((p) => p.at >= dayStart && p.at < end).length);

  const bs = d.builds.filter((b) => b.at >= dayStart && b.at < end);
  put("build.started", bs.length);
  put("build.succeeded", bs.filter(isSuccess).length);
  put("build.failed", bs.filter((b) => b.status === "failed").length);
  put("build.first_try", bs.filter(isFirstTry).length);
  put("build.refine", bs.filter((b) => b.isRefine).length);
  put("build.cost_usd", Math.round(bs.reduce((s, b) => s + b.costUsd, 0) * 10000) / 10000);
  const lanes = new Map<string, number>();
  for (const b of bs) for (const l of b.lanes.length ? b.lanes : ["none"]) lanes.set(l, (lanes.get(l) ?? 0) + 1);
  for (const [l, n] of lanes) put("build.lane", n, `lane=${dimOk(l)}`);

  const led = d.ledger.filter((l) => l.at >= dayStart && l.at < end);
  let top = 0, plan = 0, purchases = 0, spent = 0, bought = 0;
  for (const l of led) {
    if (l.kind === "spend") spent += Math.abs(l.delta);
    if (l.kind !== "purchase") continue;
    const m = (l.meta && typeof l.meta === "object" && !Array.isArray(l.meta) ? l.meta : {}) as Record<string, unknown>;
    const paid = l.source === "plan" ? m.amountPaid : m.paidCents;
    if (typeof paid !== "number" || paid <= 0 || m.livemode === false) continue;
    purchases++; bought += Math.max(0, l.delta);
    if (l.source === "plan") plan += paid; else top += paid;
  }
  put("money.revenue_cents", top + plan);
  put("money.topup_cents", top);
  put("money.plan_cents", plan);
  put("money.purchases", purchases);
  put("tokens.purchased", bought);
  put("tokens.spent", spent);
  return out;
}

/** Upsert rows by SET. Returns rows written. Never throws. */
export async function writeRollup(rows: RollupRow[]): Promise<number> {
  let n = 0;
  for (const r of rows) {
    try {
      await cyrusDb.$executeRaw`INSERT INTO "CyrusDailyMetrics" ("id","date","key","dim","value","updatedAt") VALUES (${randomUUID()}, ${new Date(r.date)}, ${r.key}, ${r.dim}, ${r.value}, NOW()) ON CONFLICT ("date","key","dim") DO UPDATE SET "value" = EXCLUDED."value", "updatedAt" = NOW()`;
      n++;
    } catch { return n; } // table missing: stop (the page reports it)
  }
  return n;
}

export type RollupResult = { days: number; rows: number; purged: number; skipped?: string };

/** The nightly job: roll up yesterday and the two days before it (late data), then purge raw events past retention. */
export async function runRollup(now = Date.now(), env: Record<string, string | undefined> = process.env): Promise<RollupResult> {
  if (!analyticsEnabled(env)) return { days: 0, rows: 0, purged: 0, skipped: "CYRUS_ANALYTICS is off" };
  const data = await loadAnalytics(4, now);
  const today = utcDay(now);
  let rows = 0;
  const dayStarts = [today - DAY, today - 2 * DAY, today - 3 * DAY];
  for (const ds of dayStarts) rows += await writeRollup(rollupDay(data, ds));
  // purge only AFTER the aggregates of the days about to expire were written (the 90-day-old day was rolled up long ago)
  const purged = await purgeRawEvents(now);
  return { days: dayStarts.length, rows, purged };
}

export const rollupDayKey = (ms: number) => dayKey(ms);
