// Cyrus analytics WEEKLY DIGEST (OFF by default): one staff email on Monday with last week's numbers next to the week before.
// Same visual structure as Nxeon's email shell v2 (rounded shell, header row, hero band with eyebrow + headline + lead, a
// button, footer) in the Cyrus palette, like lib/cyrus/notify/templates.ts. Pure render + a server sender.
// Switches: setting cyrus_analytics_digest_enabled (default false) + cyrus_analytics_digest_to (emails of EXISTING accounts)
// + the Cyrus sender cyrus_mail_from (cyrus.my only) + a host with mail. Sent at most once per ISO week.
import { getHost } from "../host";
import { validCyrusSender, MAIL_FROM_SETTING } from "../notify/events";
import { loadAnalytics } from "./facts";
import { buildReport, type Report } from "./report";
import { DAY } from "./metrics";

export const DIGEST_ENABLED = "cyrus_analytics_digest_enabled";
export const DIGEST_TO = "cyrus_analytics_digest_to";
export const DIGEST_LAST = "cyrus_analytics_digest_last";

const esc = (s: unknown) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
const n0 = (x: number | null | undefined) => (x === null || x === undefined || !Number.isFinite(x) ? "n/a" : Math.round(x).toLocaleString("en-US"));
const pc = (x: number | null) => (x === null ? "n/a" : `${Math.round(x * 100)}%`);
const usd = (x: number) => `$${x.toFixed(2)}`;

export type DigestLine = { label: string; now: string; prev: string; note?: string };

/** The numbers of the digest: this week (the report window) beside the week before. */
export function digestLines(cur: Report, prev: Report): DigestLine[] {
  const L = (label: string, a: number | null, b: number | null, fmt: (x: number | null) => string = n0, note?: string): DigestLine => ({ label, now: fmt(a), prev: fmt(b), note });
  return [
    L("Human page views", cur.web.summary.views, prev.web.summary.views),
    L("Visitors (consented sample)", cur.web.summary.visitors, prev.web.summary.visitors, n0, "visitors who accepted analytics; never extrapolated"),
    L("Page views from AI assistants", cur.web.aiAssistants.reduce((s, x) => s + x.views, 0), prev.web.aiAssistants.reduce((s, x) => s + x.views, 0)),
    L("Accounts first seen", cur.accounts.inWindow, prev.accounts.inWindow),
    L("Activated (a successful build)", cur.accounts.activated, prev.accounts.activated),
    L("Installed on a server", cur.accounts.installed, prev.accounts.installed),
    L("Paying accounts (first payment)", cur.accounts.paying, prev.accounts.paying),
    L("Builds", cur.product.builds, prev.product.builds),
    L("Build success rate", cur.product.successRate, prev.product.successRate, pc),
    L("Revenue (live)", cur.money.totalCents / 100, prev.money.totalCents / 100, (x) => (x === null ? "n/a" : usd(x))),
    L("AI cost", cur.money.aiCostUsd, prev.money.aiCostUsd, (x) => (x === null ? "n/a" : usd(x))),
  ];
}

export function renderDigest(cur: Report, prev: Report, ctx: { appBase: string; weekLabel: string }): { subject: string; html: string; text: string } {
  const lines = digestLines(cur, prev);
  const base = ctx.appBase.replace(/\/$/, "");
  const link = `${base}/admin/cyrus/analytics`;
  const top = cur.accounts.funnel.map((s, i) => ({ s, i })).filter((x) => x.i > 0 && x.s.ofPrev !== null).sort((a, b) => (a.s.ofPrev as number) - (b.s.ofPrev as number))[0];
  const lead = top && cur.accounts.inWindow > 0
    ? `Biggest drop-off this week: ${top.s.label} (${pc(top.s.ofPrev)} of those who reached the step before).`
    : cur.accounts.inWindow === 0 ? "No new Cyrus accounts were first seen this week." : "Numbers for the last 7 days next to the 7 days before.";
  const subject = `Cyrus analytics, week of ${ctx.weekLabel}`;
  const rows = lines.map((l) => `<tr><td style="padding:8px 0;border-top:1px solid #1a2034;color:#cfd3e0;font-size:14px;">${esc(l.label)}${l.note ? `<br><span style="color:#8a8fa3;font-size:12px;">${esc(l.note)}</span>` : ""}</td><td align="right" style="padding:8px 0;border-top:1px solid #1a2034;color:#ffffff;font-size:15px;font-weight:700;">${esc(l.now)}</td><td align="right" style="padding:8px 0 8px 14px;border-top:1px solid #1a2034;color:#8a8fa3;font-size:13px;">${esc(l.prev)}</td></tr>`).join("");
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark light"></head>
<body bgcolor="#050508" style="margin:0;padding:0;background:#050508;color:#ffffff;font-family:Inter,Segoe UI,Helvetica,Arial,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#050508" style="background:#050508;"><tr><td align="center" style="padding:32px 14px 40px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" bgcolor="#0a0d1c" style="width:100%;max-width:600px;background:#0a0d1c;border:1px solid #1d2442;border-radius:22px;">
<tr><td style="padding:24px 40px 20px 40px;border-bottom:1px solid #1a2034;font-size:15px;font-weight:700;color:#ffffff;">Cyrus <span style="color:#8a8fa3;font-weight:400;">admin</span></td></tr>
<tr><td style="padding:36px 40px 12px 40px;background:#0a0d1c;background-image:radial-gradient(ellipse at 100% 0%,#1b2a6b 0%,#0a0d1c 60%);">
<div style="margin:0 0 14px;font-size:13px;line-height:16px;font-weight:700;letter-spacing:1.8px;text-transform:uppercase;color:#9cc0ff;">Weekly analytics</div>
<h1 style="margin:0 0 14px;font-size:30px;line-height:36px;font-weight:800;letter-spacing:-.6px;color:#ffffff;">Week of ${esc(ctx.weekLabel)}</h1>
<p style="margin:0;font-size:15px;line-height:24px;color:#cfd3e0;">${esc(lead)}</p></td></tr>
<tr><td style="padding:12px 40px 8px 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="font-size:11px;color:#8a8fa3;text-transform:uppercase;letter-spacing:1px;">Metric</td><td align="right" style="font-size:11px;color:#8a8fa3;text-transform:uppercase;letter-spacing:1px;">This week</td><td align="right" style="font-size:11px;color:#8a8fa3;text-transform:uppercase;letter-spacing:1px;padding-left:14px;">Before</td></tr>${rows}</table></td></tr>
<tr><td style="padding:18px 40px 30px 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" bgcolor="#3d7bff" style="border-radius:12px;background:#3d7bff;"><a href="${esc(link)}" style="display:block;padding:14px 20px;color:#ffffff;font-weight:700;font-size:15px;text-decoration:none;">Open the analytics</a></td></tr></table></td></tr>
<tr><td align="center" style="padding:0 40px 26px 40px;font-size:12px;line-height:19px;color:#8a8fa3;">Human traffic only; visitors are a consented sample; nothing here is estimated. Turn this email off in Cyrus admin, Audit &amp; settings (${esc(DIGEST_ENABLED)}).</td></tr>
</table></td></tr></table></body></html>`;
  const text = [subject, "", lead, "", ...lines.map((l) => `${l.label}: ${l.now} (before: ${l.prev})${l.note ? `  [${l.note}]` : ""}`), "", `Open: ${link}`, "Human traffic only; visitors are a consented sample; nothing is estimated."].join("\n");
  return { subject, html, text };
}

/** ISO-ish week key (UTC Monday date) of a time. */
export const weekKey = (ms: number) => { const d = Math.floor(ms / DAY) * DAY; const dow = (new Date(d).getUTCDay() + 6) % 7; return new Date(d - dow * DAY).toISOString().slice(0, 10); };

export type DigestResult = { sent: number; skipped?: string };

/** Monday on or after 07:00 UTC, once per week, only when enabled. Inert (and cheap) otherwise. */
export async function digestSweep(now = Date.now(), env: Record<string, string | undefined> = process.env): Promise<DigestResult> {
  const host = getHost();
  if (!(await host.settings.getBool(DIGEST_ENABLED, false))) return { sent: 0, skipped: "off" };
  const dt = new Date(now);
  if (dt.getUTCDay() !== 1 || dt.getUTCHours() < 7) return { sent: 0, skipped: "not Monday morning (UTC)" };
  const wk = weekKey(now);
  if ((await host.settings.get(DIGEST_LAST, "")) === wk) return { sent: 0, skipped: "already sent this week" };
  if (!host.mail) return { sent: 0, skipped: "this host has no mail" };
  const from = (await host.settings.get(MAIL_FROM_SETTING, "")).trim();
  if (!from || !validCyrusSender(from)) return { sent: 0, skipped: "no valid cyrus.my sender (cyrus_mail_from)" };
  const to = (await host.settings.get(DIGEST_TO, "")).split(/[,\s;]+/).map((e) => e.trim().toLowerCase()).filter(Boolean).slice(0, 10);
  if (!to.length) return { sent: 0, skipped: "no recipients" };
  const d = await loadAnalytics(14, now);
  const cur = buildReport({ ...d, days: 7, from: now - 7 * DAY });
  const prev = buildReport({ ...d, now: now - 7 * DAY, from: now - 14 * DAY, days: 7 });
  const msg = renderDigest(cur, prev, { appBase: (env.CYRUS_PUBLIC_BASE || env.APP_URL || "https://nxeon.cloud").replace(/\/$/, ""), weekLabel: new Date(now - 7 * DAY).toISOString().slice(0, 10) });
  // claim the week BEFORE sending: a crash after a send must not send twice; a failed send is retried next week at worst
  await host.settings.writeStored(DIGEST_LAST, wk);
  let sent = 0;
  for (const email of to) {
    const u = await host.users.find(email).catch(() => null);
    if (!u) continue;
    if (await host.mail.send({ to: u.email, from, subject: msg.subject, html: msg.html, text: msg.text, userId: u.id }).catch(() => false)) sent++;
  }
  await host.audit.append({ userId: null, action: "cyrus.analytics.digest", detail: `sent ${sent} of ${to.length}`, category: "cyrus", target: wk }).catch(() => {});
  return { sent };
}
