  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark light"></head>
<body bgcolor="#050508" style="margin:0;padding:0;background:#050508;color:#ffffff;font-family:Inter,Segoe UI,Helvetica,Arial,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#050508" style="background:#050508;"><tr><td align="center" style="padding:32px 14px 40px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" bgcolor="#0a0d1c" style="width:100%;max-width:600px;background:#0a0d1c;border:1px solid #1d2442;border-radius:22px;">
<tr><td style="padding:24px 40px 20px 40px;border-bottom:1px solid #1a2034;font-size:15px;font-weight:700;color:#ffffff;">Cyrus <span style="color:#8a8fa3;font-weight:400;">admin</span></td></tr>
<tr><td style="padding:36px 40px 12px 40px;background:#0a0d1c;background-image:radial-gradient(ellipse at 100% 0%,#1b2a6b 0%,#0a0d1c 60%);">
<div style="margin:0 0 14px;font-size:13px;line-height:16px;font-weight:700;letter-spacing:1.8px;text-transform:uppercase;color:#9cc0ff;">Weekly analytics</div>
<h1 style="margin:0 0 14px;font-size:30px;line-height:36px;font-weight:800;letter-spacing:-.6px;color:#ffffff;">Week of ${esc(ctx.weekLabel)}</h1>
<p style="margin:0;font-size:15px;line-height:24px;color:#cfd3e0;">${esc(lead)}</p></td></tr>
<tr><td style="padding:12px 40px 8px 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="font-size:11px;color:#8a8fa3;text-transform:uppercase;letter-spacing:1px;">Metric</td><td align="right" style="font-size:11px;color:#8a8fa3;text-transform:uppercase;letter-spacing:1px;">This week</td><td align="right" style="font-size:11px;color:#8a8fa3;text-transform:uppercase;letter-spacing:1px;padding-left:14px;">Before</td></tr>${rows}</table></td></tr>
<tr><td style="padding:18px 40px 30px 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" bgcolor="#3d7bff" style="border-radius:12px;background:#3d7bff;"><a href="${esc(link)}" style="display:block;padding:14px 20px;color:#ffffff;font-weight:700;font-size:15px;text-decoration:none;">Open the analytics</a></td></tr></table></td></tr>
<tr><td align="center" style="padding:0 40px 26px 40px;font-size:12px;line-height:19px;color:#8a8fa3;">Human traffic only; visitors are a consented sample; nothing here is estimated. Turn this email off in Cyrus admin, Audit &amp; settings (${esc(DIGEST_ENABLED)}).</td></tr>
</table></td></tr></table></body></html>`;
  const text = [subject, "", lead, "", ...lines.map((l) => `${l.label}: ${l.now} (before: ${l.prev})${l.note ? `  [${l.note}]` : ""}`), "", `Open: ${link}`, "Human traffic only; visitors are a consented sample; nothing is estimated."].join("\n");
