/** ISO-ish week key (UTC Monday date) of a time. */
export const weekKey = (ms: number) => { const d = Math.floor(ms / DAY) * DAY; const dow = (new Date(d).getUTCDay() + 6) % 7; return new Date(d - dow * DAY).toISOString().slice(0, 10); };

export type DigestResult = { sent: number; skipped?: string };

/** Monday on or after 07:00 UTC, once per week, only when enabled. Inert (and cheap) otherwise. */
export async function digestSweep(now = Date.now(), env: Record<string, string | undefined> = process.env): Promise<DigestResult> {
  const host = getHost();
  if (!(await host.settings.getBool(DIGEST_ENABLED, false))) return { sent: 0, skipped: "off" };
  const dt = new Date(now);
  if (dt.getUTCDay() !== 1 || dt.getUTCHours() < 7) return { sent: 0, skipped: "not Monday morning (UTC)" };
  const wk = weekKey(now);
  if ((await host.settings.get(DIGEST_LAST, "")) === wk) return { sent: 0, skipped: "already sent this week" };
  if (!host.mail) return { sent: 0, skipped: "this host has no mail" };
  const from = (await host.settings.get(MAIL_FROM_SETTING, "")).trim();
  if (!from || !validCyrusSender(from)) return { sent: 0, skipped: "no valid cyrus.my sender (cyrus_mail_from)" };
  const to = (await host.settings.get(DIGEST_TO, "")).split(/[,\s;]+/).map((e) => e.trim().toLowerCase()).filter(Boolean).slice(0, 10);
  if (!to.length) return { sent: 0, skipped: "no recipients" };
  const d = await loadAnalytics(14, now);
  const cur = buildReport({ ...d, days: 7, from: now - 7 * DAY });
  const prev = buildReport({ ...d, now: now - 7 * DAY, from: now - 14 * DAY, days: 7 });
  const msg = renderDigest(cur, prev, { appBase: (env.CYRUS_PUBLIC_BASE || env.APP_URL || "https://nxeon.cloud").replace(/\/$/, ""), weekLabel: new Date(now - 7 * DAY).toISOString().slice(0, 10) });
  // claim the week BEFORE sending: a crash after a send must not send twice; a failed send is retried next week at worst
  await host.settings.writeStored(DIGEST_LAST, wk);
  let sent = 0;
  for (const email of to) {
    const u = await host.users.find(email).catch(() => null);
    if (!u) continue;
    if (await host.mail.send({ to: u.email, from, subject: msg.subject, html: msg.html, text: msg.text, userId: u.id }).catch(() => false)) sent++;
  }
  await host.audit.append({ userId: null, action: "cyrus.analytics.digest", detail: `sent ${sent} of ${to.length}`, category: "cyrus", target: wk }).catch(() => {});
  return { sent };
}
EOF

