    case "lanes": return toCsv(["lane", "builds", "finished", "succeeded", "first_try", "success_pct", "first_try_pct", "ai_cost_usd", "cost_per_success_usd"], r.product.lanes.map((l) => [l.lane, l.builds, l.finished, l.succeeded, l.firstTry, rate(l.successRate), rate(l.firstTryRate), Math.round(l.costUsd * 1000) / 1000, l.costPerSuccess === null ? "" : Math.round(l.costPerSuccess * 1000) / 1000]));
