mkdir -p app/api/cyrus/analytics/hit; cat > app/api/cyrus/analytics/hit/route.ts <<'EOF'
import { headers } from "next/headers";
import { NextResponse } from "next/server";
import { checkRateLimit } from "@/lib/rate-limit";
import { clientIp, UNKNOWN_IP } from "@/lib/rate-limit";
import { classifyHit } from "@/lib/bots/classify";
import { activeIpFlag } from "@/lib/bots/ip-flags";
import { parseUserAgent } from "@/lib/ua-parse";
import { countryFromIp } from "@/lib/geo-ip";
import { CYRUS_HOST_HEADER } from "@/lib/cyrus/bridge/config";
import { decideHit, optOutSignal } from "@/lib/cyrus/analytics/web";
import { analyticsEnabled, bufferBotHit, recordWebRow } from "@/lib/cyrus/analytics/store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Cyrus web analytics collector (docs/cyrus/21-analytics.md). Same-origin POST from the cyrus.my landing beacon
 * (apps/cyrus-site/src/assets/js/a.js) and from the Cyrus app pages (components/cyrus/analytics/CyrusTracker.tsx).
 *
 *  - OFF unless CYRUS_ANALYTICS=1 (then it answers 204 and stores nothing).
 *  - Do Not Track / Sec-GPC: dropped before anything else, nothing stored, nothing counted.
 *  - No analytics consent (the cyrus_consent cookie, read HERE, never trusted from the body): an identifier-free hit. With
 *    consent: a rotating random visitor id and session id.
 *  - Bots (UA catalogue, datacenter or flagged address, navigator.webdriver) are COUNTED (CyrusDailyMetrics web.bot_hits),
 *    never stored as events.
 *  - The IP is used for the rate limit, the bot verdict and a country lookup, then discarded: no table holds it.
 * Always answers 204 (a beacon has no use for a body, and a probe learns nothing).
 */
const NO = () => new NextResponse(null, { status: 204, headers: { "cache-control": "no-store" } });

export async function POST(req: Request) {
  try {
    if (!analyticsEnabled()) return NO();
    const h = await headers();
    // the opt-out check comes first and is cheap: nothing below runs for a visitor who said no
    if (optOutSignal({ dnt: h.get("dnt"), secGpc: h.get("sec-gpc") })) return NO();
    const ip = clientIp(req.headers);
    const rl = checkRateLimit(`cy:a:${ip === UNKNOWN_IP ? "unknown" : ip}`, { max: 90, windowMs: 60_000 });
    if (!rl.ok) return NO();
    const len = Number(req.headers.get("content-length") ?? 0);
    if (len > 2048) return NO();
    let body: unknown = null;
    try { body = JSON.parse((await req.text()).slice(0, 2048)); } catch { return NO(); }
    const host = (h.get("host") ?? "").toLowerCase().split(":")[0];
    const ua = (h.get("user-agent") ?? "").slice(0, 400);
    if (!ua) return NO();
    const wd = body && typeof body === "object" && ((body as { wd?: unknown }).wd === 1 || (body as { wd?: unknown }).wd === true);
    const flag = ip === UNKNOWN_IP ? null : await activeIpFlag(ip).catch(() => null);
    const verdict = classifyHit({ ua, ip: ip === UNKNOWN_IP ? null : ip, userId: null, webdriver: wd ? true : null, ipFlag: flag });
    const dec = decideHit({
      enabled: true, onCyrusHost: h.get(CYRUS_HOST_HEADER) === "1", host,
      headers: { dnt: h.get("dnt"), secGpc: h.get("sec-gpc"), cookie: h.get("cookie"), origin: h.get("origin") },
      body, bot: { isBot: verdict.isBot, botKind: verdict.botKind },
      country: ip === UNKNOWN_IP ? null : countryFromIp(ip), deviceType: parseUserAgent(ua).deviceType ?? null, now: Date.now(),
    });
    if (dec.kind === "bot") bufferBotHit(dec.botKind);
    else if (dec.kind === "store") await recordWebRow(dec.row);
  } catch {
    /* analytics never surfaces an error to the page */
  }
  return NO();
}
EOF
