  function ck(k) { var m = d.cookie.match("(?:^|; )" + k + "=([^;]*)"); return m ? m[1] : ""; }
  function rid() { var a = new Uint8Array(16), o = "", i; (w.crypto || {}).getRandomValues && w.crypto.getRandomValues(a); for (i = 0; i < 16; i++) o += (a[i] % 36).toString(36); return o; }
