    var t = JSON.parse(w.sessionStorage.getItem("cyrus_sid") || "{}");
    s = t.i && now - t.t < 1800000 ? t.i : rid();
    w.sessionStorage.setItem("cyrus_sid", JSON.stringify({ i: s, t: now }));
  } catch (e) { c = 0; }
  var h = ""; try { h = d.referrer ? new URL(d.referrer).hostname : ""; } catch (e) {}
  function g(k) { return Q.get(k) || undefined; }
  function send(e) {
    if (S[e]) return; S[e] = 1;
    var b = { e: e, p: l.pathname, r: h, us: g("utm_source"), um: g("utm_medium"), uc: g("utm_campaign"), wd: n.webdriver ? 1 : 0 };
    if (c) { b.v = v; b.s = s; b.n = nw; b.f = g("ref") || g("partner"); }
    n.sendBeacon("/api/cyrus/analytics/hit", new Blob([JSON.stringify(b)], { type: "text/plain" }));
  }
  send("view");
  var tk = 0;
  w.addEventListener("scroll", function () {
    if (tk) return; tk = 1;
    w.requestAnimationFrame(function () {
      tk = 0;
      var e = d.documentElement, r = (w.scrollY + w.innerHeight) / Math.max(e.scrollHeight, 1);
      if (r >= 0.5) send("scroll50"); if (r >= 0.9) send("scroll90");
    });
  }, { passive: true });
  d.addEventListener("focusin", function (e) { if (e.target && e.target.id === "promptText") send("prompt_focus"); });
  d.addEventListener("submit", function (e) { if (e.target && e.target.id === "promptForm") send("prompt_submit"); }, true);
  d.addEventListener("click", function (e) {
    var a = e.target && e.target.closest ? e.target.closest("a[href]") : null, u;
    if (!a) return;
    try { u = new URL(a.href, l.href); } catch (x) { return; }
    if (u.origin !== l.origin) return;
    if (/^\/sign-in(\/|$)/.test(u.pathname)) send("signin_click"); else if (/^\/sign-up(\/|$)/.test(u.pathname)) send("signup_click");
  }, true);
  var pl = d.getElementById("plans");
  if (pl && w.IntersectionObserver) new IntersectionObserver(function (o) { if (o[0].isIntersecting) send("plans_view"); }, { threshold: 0.3 }).observe(pl);
})(document, window, navigator, location);
