// Cyrus analytics, BROWSER half (pure, client-safe): builds the beacon body for a page view of the Cyrus app pages
// (components/cyrus/analytics/CyrusTracker.tsx). The static landing has its own tiny script (apps/cyrus-site/src/assets/js/a.js);
// both follow the same rules and test/cyrus-analytics.test.ts runs both against the same cases.
import { VID_COOKIE, VID_ROTATE_DAYS, cookieValue, vidExpired } from "./web";
import { parseConsent } from "./consent";

export type ClientEnv = {
  doNotTrack?: string | null;
  globalPrivacyControl?: boolean;
  /** document.cookie */
  cookie: string;
  now: number;
  referrer: string;
  search: string;
  pathname: string;
  webdriver?: boolean;
  /** 16 random chars [a-z0-9] */
  random: () => string;
  session: { get(): string | null; set(v: string): void } | null;
  setCookie: (v: string) => void;
};

export type ViewBody = { e: "view"; p: string; r: string; us: string | null; um: string | null; uc: string | null; wd: 0 | 1; v?: string; s?: string; n?: 0 | 1; f?: string | null };

/** null = send nothing (Do Not Track or Global Privacy Control). No analytics consent = no identifier fields at all. */
export function viewBody(env: ClientEnv): ViewBody | null {
  if (/^(1|yes)$/.test(env.doNotTrack ?? "") || env.globalPrivacyControl === true) return null;
  const q = new URLSearchParams(env.search);
  let host = "";
  try { host = env.referrer ? new URL(env.referrer).hostname : ""; } catch { host = ""; }
  const body: ViewBody = { e: "view", p: env.pathname, r: host, us: q.get("utm_source"), um: q.get("utm_medium"), uc: q.get("utm_campaign"), wd: env.webdriver ? 1 : 0 };
  const consent = parseConsent(cookieValue(env.cookie.replace(/; /g, ";"), "cyrus_consent"));
  if (!consent?.analytics || env.now - consent.at > 180 * 86_400_000) return body;
  // rotating anonymous id: random, 30 days, replaced (never extended) after that
  const raw = (cookieValue(env.cookie.replace(/; /g, ";"), VID_COOKIE) ?? "").split(".");
  let vid = "", isNew: 0 | 1 = 0;
  const created = Number(raw[1]) * 1000;
  if (/^[a-z0-9]{12,32}$/.test(raw[0] ?? "") && !vidExpired(created, env.now)) vid = raw[0];
  else { vid = env.random(); isNew = 1; env.setCookie(`${VID_COOKIE}=${vid}.${Math.floor(env.now / 1000)}; path=/; max-age=${VID_ROTATE_DAYS * 86400}; SameSite=Lax`); }
  let sid = "";
  try {
    const t = JSON.parse(env.session?.get() ?? "null") as { i?: string; t?: number } | null;
    sid = t?.i && typeof t.t === "number" && env.now - t.t < 30 * 60_000 ? t.i : env.random();
    env.session?.set(JSON.stringify({ i: sid, t: env.now }));
  } catch { sid = env.random(); }
  return { ...body, v: vid, s: sid, n: isNew, f: q.get("ref") };
}
EOF
cat > components/cyrus/analytics/CyrusTracker.tsx <<'EOF'
"use client";
// First-party page-view beacon for the Cyrus app pages on cyrus.my (docs/cyrus/21-analytics.md). Same rules as the landing's
// a.js: Do Not Track / Global Privacy Control send nothing, no analytics consent sends no identifier. The server decides again
// (CYRUS_ANALYTICS, consent cookie, bots); this component only builds the body (lib/cyrus/analytics/client.ts). It renders nothing.
import { useEffect } from "react";
import { usePathname } from "next/navigation";
import { viewBody } from "@/lib/cyrus/analytics/client";

const rid = () => { const a = new Uint8Array(16); crypto.getRandomValues(a); return Array.from(a, (x) => (x % 36).toString(36)).join(""); };

export function CyrusTracker() {
  const path = usePathname();
  useEffect(() => {
    try {
      const nav = navigator as Navigator & { globalPrivacyControl?: boolean };
      const body = viewBody({
        doNotTrack: nav.doNotTrack, globalPrivacyControl: nav.globalPrivacyControl === true, cookie: document.cookie, now: Date.now(),
        referrer: document.referrer, search: location.search, pathname: path || location.pathname, webdriver: nav.webdriver === true, random: rid,
        session: { get: () => sessionStorage.getItem("cyrus_sid"), set: (v) => sessionStorage.setItem("cyrus_sid", v) },
        setCookie: (v) => { document.cookie = v + (window.isSecureContext ? ";Secure" : ""); },
      });
      if (!body) return;
      const blob = new Blob([JSON.stringify(body)], { type: "text/plain" });
      if (!navigator.sendBeacon?.("/api/cyrus/analytics/hit", blob)) void fetch("/api/cyrus/analytics/hit", { method: "POST", body: blob, keepalive: true }).catch(() => {});
    } catch { /* analytics never breaks a page */ }
  }, [path]);
  return null;
}
EOF
