// crawler IP lists, datacenter ranges, one indexed BotIpFlag lookup). No
// DNS here — FCrDNS verification happens asynchronously in the worker.
const webdriver = body.wd === true ? true : body.wd === false ? false : null;
const ipFlag = await activeIpFlag(ip);
const bot = classifyHit({ ua, ip, userId, webdriver, ipFlag });
if (bot.isBot && bot.crawlerId) {
  // Self-declared crawlers rendering JS can fire this beacon for every page
  // they crawl; cap their rows globally per crawler so a crawl of 65k pages
  // can't balloon the Visit table (crawler volume is measured from the
  // access log instead — worker/crawler-log.ts).
  const cap = checkRateLimit(`trackbot:${bot.crawlerId}`, { max: 300, windowMs: 60_000 });
  if (!cap.ok) return NextResponse.json({ ok: true });
}

// Cyrus analytics (2026-10-15): the host and product dimension. Written only while the two nullable Visit columns
// exist in the database; until `prisma db push` runs the insert is retried WITHOUT them, so a page view is never
// lost to this change (docs/cyrus/21-analytics.md). NULL = a row from before this = Nxeon legacy.
const dims = trackDimensions(req.headers.get("host"), path, bridgeConfig().cyrusHosts);
const visitData = {
    ip,
    path,
    referrer,
    ua,
    deviceType,
    os,
    browser,
    kind,
    userId,
    visitorId,
    sessionId: cleanId(body.sessionId),
    pvid: cleanId(body.pvid),
    isEntry: body.isEntry === true,
    utmSource,
    utmMedium,
    utmCampaign: cleanUtm(body.utmCampaign),
    gclid,
    isBot: bot.isBot,
    botKind: bot.botKind,
    botReason: bot.botReason,
    webdriver,
};
try {
  if (Date.now() < hostColsMissingUntil) await db.visit.create({ data: visitData });
  else await db.visit.create({ data: { ...visitData, host: dims.host, product: dims.product } });
} catch (e) {
  // column does not exist yet (P2022 / "Unknown argument" from an older generated client): fall back, remember for 5 minutes
  if (!/host|product|P2022|Unknown argument/i.test(String((e as Error)?.message ?? e))) throw e;
  hostColsMissingUntil = Date.now() + 5 * 60_000;

  // Cyrus capacity (CYRUS_CAPACITY_UI only; off = nothing added): the builder's queue right now
  const capacity = capacityUiOn() ? planCapacity((await svcHealthFresh().catch(() => null)) as Parameters<typeof planCapacity>[0]) : null;
  if (capacity) Object.assign(extra, { capacity });
  if (!coach) return NextResponse.json({ ...out, buildable, ...extra }, { headers: { "Cache-Control": "no-store" } });
  const base = change ? (parseChangeContext(body.base) ?? { name: "this mod" }) : null;
  const report = analyzePrompt({ text: prompt, version: mcVersion, change: base, lanes: out.plan.lanes, held, techniques: techniquesOn() });
  return NextResponse.json({ ...out, buildable, ...extra, coach: report, coachHeld: held }, { headers: { "Cache-Control": "no-store" } });
}

